def apply_formula(filepath, sheet_name, start_cell, formula, end_cell=None, **_extra):
    import json, os, datetime, time, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0038000" if __import__("os").path.isdir("./environment_mix/0038000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_id(prefix):
        ms = int(time.time() * 1000)
        r = random.getrandbits(80)
        v = (ms << 80) | r
        chars = []
        for _ in range(26):
            chars.append(_B32[v & 31])
            v >>= 5
        return prefix + "".join(reversed(chars))

    _A1_RE = re.compile(r"^\$?([A-Z]{1,3})\$?([1-9][0-9]*)$")
    def _col_to_num(col):
        n = 0
        for ch in col:
            n = n * 26 + (ord(ch) - 64)
        return n

    def _parse_a1(addr):
        if not isinstance(addr, str):
            return None
        s = addr.strip().upper().replace("$", "")
        m = _A1_RE.match(s)
        if not m:
            return None
        col_s, row_s = m.group(1), m.group(2)
        col_n = _col_to_num(col_s)
        try:
            row_n = int(row_s)
        except Exception:
            return None
        if col_n < 1 or col_n > 16384 or row_n < 1 or row_n > 1048576:
            return None
        return {"col": col_n, "row": row_n, "a1": f"{col_s}{row_n}"}

    def _rect_ok(a, b):
        return b["col"] >= a["col"] and b["row"] >= a["row"]

    def _log_op(wb_id, ws_id, status, start_cell_a1=None, end_cell_a1=None, error_message=None, result_payload=None):
        ops = _load("range_operations.json")
        op_id = _new_id("exop_")
        row = {
            "id": op_id,
            "workbook_id": wb_id,
            "worksheet_id": ws_id,
            "tool_name": "apply_formula",
            "operation_scope": "range" if end_cell_a1 else "cell",
            "start_cell": start_cell_a1,
            "end_cell": end_cell_a1,
            "source_range": None,
            "destination_start_cell": None,
            "shift_direction": None,
            "formula": formula if isinstance(formula, str) else None,
            "format_spec": None,
            "write_payload": None,
            "read_preview_only": None,
            "request_params": {
                "filepath": filepath,
                "sheet_name": sheet_name,
                "start_cell": start_cell,
                "end_cell": end_cell,
                "formula": formula,
            },
            "result_payload": result_payload,
            "error_message": error_message,
            "status": status,
            "started_at": now,
            "completed_at": now,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("range_operations.json", ops)
        return row

    # ---- validate inputs ----
    if not isinstance(filepath, str) or not filepath.strip():
        op = _log_op("", None, "failed", error_message="filepath must be a non-empty string")
        return _err("VALIDATION_ERROR", "filepath must be a non-empty string", operation=op)
    if not isinstance(sheet_name, str) or not sheet_name.strip():
        op = _log_op("", None, "failed", error_message="sheet_name must be a non-empty string")
        return _err("VALIDATION_ERROR", "sheet_name must be a non-empty string", operation=op)
    if not isinstance(start_cell, str) or not start_cell.strip():
        op = _log_op("", None, "failed", error_message="start_cell must be a non-empty A1 string")
        return _err("VALIDATION_ERROR", "start_cell must be a non-empty A1 string", operation=op)
    if not isinstance(formula, str) or not formula.strip():
        op = _log_op("", None, "failed", error_message="formula must be a non-empty string")
        return _err("VALIDATION_ERROR", "formula must be a non-empty string", operation=op)

    sc = _parse_a1(start_cell)
    if not sc:
        op = _log_op("", None, "failed", error_message=f"Invalid A1 reference: {start_cell}")
        return _err("VALIDATION_ERROR", "Invalid A1 reference for start_cell", start_cell=start_cell, operation=op)

    ec = None
    if end_cell is not None:
        if not isinstance(end_cell, str) or not end_cell.strip():
            op = _log_op("", None, "failed", error_message="end_cell must be a non-empty A1 string when provided")
            return _err("VALIDATION_ERROR", "end_cell must be a non-empty A1 string when provided", operation=op)
        ec = _parse_a1(end_cell)
        if not ec:
            op = _log_op("", None, "failed", error_message=f"Invalid A1 reference: {end_cell}")
            return _err("VALIDATION_ERROR", "Invalid A1 reference for end_cell", end_cell=end_cell, operation=op)
        if not _rect_ok(sc, ec):
            op = _log_op("", None, "failed", start_cell_a1=sc["a1"], end_cell_a1=ec["a1"],
                         error_message=f"Invalid range: {sc['a1']}:{ec['a1']} (non-empty rectangular ranges only)")
            return _err("VALIDATION_ERROR", "Invalid range (end_cell must be down/right of start_cell)", start_cell=sc["a1"], end_cell=ec["a1"], operation=op)

    # ---- resolve workbook by filepath (must be exactly one non-deleted; if multiple, pick best candidate) ----
    workbooks = _load("workbooks.json")
    fp = filepath.strip()
    cands = [w for w in workbooks if isinstance(w, dict) and w.get("filepath") == fp and w.get("status") != "deleted"]
    if not cands:
        op = _log_op("", None, "failed", start_cell_a1=sc["a1"], end_cell_a1=(ec["a1"] if ec else None), error_message="Workbook not found for filepath")
        return _err("NOT_FOUND", "Workbook not found", filepath=fp, operation=op)

    # prefer active, else archived/error/creating
    def _rank_wb(w):
        st = w.get("status")
        return {"active": 0, "archived": 1, "error": 2, "creating": 3}.get(st, 9)
    cands.sort(key=_rank_wb)
    wb = cands[0]
    wb_id = wb.get("id") or ""
    if not wb_id:
        op = _log_op("", None, "failed", start_cell_a1=sc["a1"], end_cell_a1=(ec["a1"] if ec else None), error_message="Workbook row missing id")
        return _err("NOT_FOUND", "Workbook not found", filepath=fp, operation=op)

    # must not allow mutations on deleted worksheets; workbook status may be archived but still readable—apply_formula is mutation so require active workbook
    if wb.get("status") != "active":
        op = _log_op(wb_id, None, "failed", start_cell_a1=sc["a1"], end_cell_a1=(ec["a1"] if ec else None),
                     error_message=f"Workbook is not writable in its current status ({wb.get('status')})")
        return _err("CONFLICT", "Workbook is not writable in its current status", status=wb.get("status"), workbook_id=wb_id, operation=op)

    # ---- resolve worksheet by name (be forgiving: trim and case-insensitive match fallback) ----
    worksheets = _load("worksheets.json")
    sn = sheet_name.strip()
    ws = None
    for row in worksheets:
        if isinstance(row, dict) and row.get("workbook_id") == wb_id and row.get("status") == "active" and row.get("name") == sn:
            ws = row
            break
    if ws is None:
        sn_u = sn.upper()
        for row in worksheets:
            if not isinstance(row, dict):
                continue
            if row.get("workbook_id") != wb_id or row.get("status") != "active":
                continue
            nm = row.get("name")
            if isinstance(nm, str) and nm.strip().upper() == sn_u:
                ws = row
                break
    if ws is None:
        op = _log_op(wb_id, None, "failed", start_cell_a1=sc["a1"], end_cell_a1=(ec["a1"] if ec else None),
                     error_message="Worksheet not found or not active")
        return _err("NOT_FOUND", "Worksheet not found or not active", sheet_name=sn, workbook_id=wb_id, operation=op)

    ws_id = ws.get("id")

    # ---- "apply" formula: offline server records audit + updates workbook hash/mtime if file exists ----
    # Formula validation: keep light; must look like an Excel formula string
    f = formula.strip()
    if not f.startswith("="):
        op = _log_op(wb_id, ws_id, "failed", start_cell_a1=sc["a1"], end_cell_a1=(ec["a1"] if ec else None),
                     error_message="Formula must start with '='")
        return _err("VALIDATION_ERROR", "formula must start with '='", operation=op)

    result_payload = {
        "applied_to": {
            "sheet_name": ws.get("name"),
            "start_cell": sc["a1"],
            "end_cell": (ec["a1"] if ec else None),
        },
        "formula": f,
        "cell_count": ((ec["col"] - sc["col"] + 1) * (ec["row"] - sc["row"] + 1)) if ec else 1,
        "note": "Offline audit-only apply; workbook file mutation is not performed by this local datastore backend.",
    }

    # opportunistically update workbook last_opened_at/updated_at; if file:// exists compute hash+size+mtime
    storage_uri = wb.get("storage_uri")
    path = None
    if isinstance(storage_uri, str) and storage_uri.startswith("file://"):
        path = storage_uri[len("file://"):]
    elif isinstance(wb.get("filepath"), str) and wb.get("filepath"):
        path = wb.get("filepath")

    wb_changed = False
    wb["last_opened_at"] = now
    wb["updated_at"] = now
    wb_changed = True

    if isinstance(path, str) and path:
        try:
            st = os.stat(path)
            wb["file_size_bytes"] = int(st.st_size)
            wb["last_modified_at"] = datetime.datetime.utcfromtimestamp(st.st_mtime).replace(microsecond=0).isoformat() + "Z"
            # best-effort hash for change detection
            import hashlib
            h = hashlib.sha256()
            with open(path, "rb") as fobj:
                for chunk in iter(lambda: fobj.read(1024 * 1024), b""):
                    h.update(chunk)
            wb["file_hash_sha256"] = h.hexdigest()
        except FileNotFoundError:
            # file missing doesn't invalidate operation recording; but workbook is active so keep as-is
            pass
        except PermissionError:
            # treat as failure to satisfy atomic write prerequisite
            op = _log_op(wb_id, ws_id, "failed", start_cell_a1=sc["a1"], end_cell_a1=(ec["a1"] if ec else None),
                         error_message="Workbook file is not accessible for update (permission denied)")
            return _err("CONFLICT", "Workbook file is not accessible for update", operation=op)

    if wb_changed:
        for i, row in enumerate(workbooks):
            if isinstance(row, dict) and row.get("id") == wb_id:
                workbooks[i] = wb
                _save("workbooks.json", workbooks)
                break

    op = _log_op(wb_id, ws_id, "succeeded", start_cell_a1=sc["a1"], end_cell_a1=(ec["a1"] if ec else None), result_payload=result_payload)

    return {
        "operation": op,
        "workbook": {"id": wb_id, "filepath": wb.get("filepath"), "status": wb.get("status"), "file_hash_sha256": wb.get("file_hash_sha256")},
        "worksheet": {"id": ws_id, "name": ws.get("name"), "status": ws.get("status")},
        "latency_ms": int((time.time() - t0) * 1000),
    }

def validate_formula_syntax(formula, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0038000" if __import__("os").path.isdir("./environment_mix/0038000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{hashlib.sha256((prefix + '|' + str(time.time_ns())).encode('utf-8')).hexdigest()[:24]}"

    if not isinstance(formula, str) or not formula.strip():
        return _err("VALIDATION_ERROR", "formula must be a non-empty string")

    # Quota/rate: simple per-minute limit using range_operations log for this tool
    ops = _load("range_operations.json")
    now_dt = datetime.datetime.utcnow()
    window_start = now_dt - datetime.timedelta(minutes=1)

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    recent = 0
    for r in ops:
        if not isinstance(r, dict):
            continue
        if r.get("tool_name") != "validate_formula_syntax":
            continue
        ts = _parse_ts(r.get("created_at"))
        if ts and ts >= window_start:
            recent += 1

    RATE_PER_MIN = 60
    if recent >= RATE_PER_MIN:
        return _err("QUOTA_EXCEEDED", "Formula validation rate limit exceeded", limit_per_minute=RATE_PER_MIN)

    t0 = time.time()
    op_id = _new_id("op")
    now = _now()

    def _validate_formula_basic(s):
        s = s.strip()
        if not s.startswith("="):
            return {"valid": False, "errors": ["Formula must start with '='"]}
        if len(s) < 2:
            return {"valid": False, "errors": ["Formula is empty after '='"]}
        bal = 0
        in_str = False
        prev = ""
        for ch in s[1:]:
            if ch == '"' and prev != "\\":
                in_str = not in_str
            if not in_str:
                if ch == "(":
                    bal += 1
                elif ch == ")":
                    bal -= 1
                    if bal < 0:
                        return {"valid": False, "errors": ["Unbalanced parentheses"]}
            prev = ch
        if in_str:
            return {"valid": False, "errors": ["Unterminated string literal"]}
        if bal != 0:
            return {"valid": False, "errors": ["Unbalanced parentheses"]}
        if any(ord(c) < 32 and c not in ("\t", "\n", "\r") for c in s):
            return {"valid": False, "errors": ["Invalid control characters in formula"]}
        # Light token sanity: forbid leading "=+" etc.
        if re.match(r"^=\s*$", s):
            return {"valid": False, "errors": ["Formula is empty"]}
        return {"valid": True, "errors": []}

    v = _validate_formula_basic(formula)
    latency_ms = int((time.time() - t0) * 1000)

    op_row = {
        "id": op_id,
        "workbook_id": "unknown",
        "worksheet_id": None,
        "tool_name": "validate_formula_syntax",
        "operation_scope": "cell",
        "start_cell": None,
        "end_cell": None,
        "source_range": None,
        "destination_start_cell": None,
        "shift_direction": None,
        "formula": formula,
        "format_spec": None,
        "write_payload": None,
        "read_preview_only": None,
        "request_params": {"formula": formula},
        "result_payload": {"valid": v["valid"], "errors": v["errors"]},
        "error_message": (None if v["valid"] else "Formula syntax invalid"),
        "status": ("succeeded" if v["valid"] else "failed"),
        "started_at": now,
        "completed_at": now,
        "created_at": now,
        "updated_at": now,
    }
    ops.append(op_row)
    _save("range_operations.json", ops)

    return {
        "operation": {"id": op_id, "status": op_row["status"], "latency_ms": latency_ms},
        "result": op_row["result_payload"],
    }

def format_range(filepath, sheet_name, start_cell, end_cell, format_spec, **_extra):
    import json, os, datetime, time, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0038000" if __import__("os").path.isdir("./environment_mix/0038000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_id(prefix):
        ms = int(time.time() * 1000)
        r = random.getrandbits(80)
        v = (ms << 80) | r
        chars = []
        for _ in range(26):
            chars.append(_B32[v & 31])
            v >>= 5
        return prefix + "".join(reversed(chars))

    _A1_RE = re.compile(r"^\$?([A-Z]{1,3})\$?([1-9][0-9]*)$")
    def _col_to_num(col):
        n = 0
        for ch in col:
            n = n * 26 + (ord(ch) - 64)
        return n
    def _parse_a1(addr):
        if not isinstance(addr, str):
            return None
        s = addr.strip().upper().replace("$", "")
        m = _A1_RE.match(s)
        if not m:
            return None
        col_s, row_s = m.group(1), m.group(2)
        col_n = _col_to_num(col_s)
        row_n = int(row_s)
        if col_n < 1 or col_n > 16384 or row_n < 1 or row_n > 1048576:
            return None
        return {"col": col_n, "row": row_n, "a1": f"{col_s}{row_n}"}
    def _rect_ok(a, b):
        return b["col"] >= a["col"] and b["row"] >= a["row"]

    def _log_op(wb_id, ws_id, status, start_cell_a1=None, end_cell_a1=None, error_message=None, result_payload=None):
        ops = _load("range_operations.json")
        op_id = _new_id("exop_")
        row = {
            "id": op_id,
            "workbook_id": wb_id,
            "worksheet_id": ws_id,
            "tool_name": "format_range",
            "operation_scope": "range",
            "start_cell": start_cell_a1,
            "end_cell": end_cell_a1,
            "source_range": None,
            "destination_start_cell": None,
            "shift_direction": None,
            "formula": None,
            "format_spec": format_spec if isinstance(format_spec, dict) else None,
            "write_payload": None,
            "read_preview_only": None,
            "request_params": {
                "filepath": filepath,
                "sheet_name": sheet_name,
                "start_cell": start_cell,
                "end_cell": end_cell,
                "format_spec": format_spec,
            },
            "result_payload": result_payload,
            "error_message": error_message,
            "status": status,
            "started_at": now,
            "completed_at": now,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("range_operations.json", ops)
        return row

    # ---- validate inputs ----
    if not isinstance(filepath, str) or not filepath.strip():
        op = _log_op("", None, "failed", error_message="filepath must be a non-empty string")
        return _err("VALIDATION_ERROR", "filepath must be a non-empty string", operation=op)
    if not isinstance(sheet_name, str) or not sheet_name.strip():
        op = _log_op("", None, "failed", error_message="sheet_name must be a non-empty string")
        return _err("VALIDATION_ERROR", "sheet_name must be a non-empty string", operation=op)
    if not isinstance(start_cell, str) or not start_cell.strip():
        op = _log_op("", None, "failed", error_message="start_cell must be a non-empty A1 string")
        return _err("VALIDATION_ERROR", "start_cell must be a non-empty A1 string", operation=op)
    if not isinstance(end_cell, str) or not end_cell.strip():
        op = _log_op("", None, "failed", error_message="end_cell must be a non-empty A1 string")
        return _err("VALIDATION_ERROR", "end_cell must be a non-empty A1 string", operation=op)
    if not isinstance(format_spec, dict):
        op = _log_op("", None, "failed", error_message="format_spec must be an object")
        return _err("VALIDATION_ERROR", "format_spec must be an object", operation=op)

    sc = _parse_a1(start_cell)
    ec = _parse_a1(end_cell)
    if not sc:
        op = _log_op("", None, "failed", error_message=f"Invalid A1 reference: {start_cell}")
        return _err("VALIDATION_ERROR", "Invalid A1 reference for start_cell", start_cell=start_cell, operation=op)
    if not ec:
        op = _log_op("", None, "failed", error_message=f"Invalid A1 reference: {end_cell}")
        return _err("VALIDATION_ERROR", "Invalid A1 reference for end_cell", end_cell=end_cell, operation=op)
    if not _rect_ok(sc, ec):
        op = _log_op("", None, "failed", start_cell_a1=sc["a1"], end_cell_a1=ec["a1"],
                     error_message=f"Invalid range: {sc['a1']}:{ec['a1']} (non-empty rectangular ranges only)")
        return _err("VALIDATION_ERROR", "Invalid range (end_cell must be down/right of start_cell)", start_cell=sc["a1"], end_cell=ec["a1"], operation=op)

    # whitelist keys (rule); allow empty object (no-op) but must still be recorded as succeeded with effect? In real services, empty format_spec is accepted as no-op but still recorded. Here we treat it as succeeded audit-only.
    allowed = {"font", "fill", "alignment", "number_format", "border"}
    bad = [k for k in format_spec.keys() if k not in allowed]
    if bad:
        op = _log_op("", None, "failed", start_cell_a1=sc["a1"], end_cell_a1=ec["a1"],
                     error_message=f"format_spec contains unsupported keys: {', '.join(sorted(bad))}")
        return _err("VALIDATION_ERROR", "format_spec contains unsupported keys", unsupported_keys=sorted(bad), operation=op)

    # ---- resolve workbook ----
    workbooks = _load("workbooks.json")
    fp = filepath.strip()
    cands = [w for w in workbooks if isinstance(w, dict) and w.get("filepath") == fp and w.get("status") != "deleted"]
    if not cands:
        op = _log_op("", None, "failed", start_cell_a1=sc["a1"], end_cell_a1=ec["a1"], error_message="Workbook not found for filepath")
        return _err("NOT_FOUND", "Workbook not found", filepath=fp, operation=op)
    def _rank_wb(w):
        st = w.get("status")
        return {"active": 0, "archived": 1, "error": 2, "creating": 3}.get(st, 9)
    cands.sort(key=_rank_wb)
    wb = cands[0]
    wb_id = wb.get("id") or ""
    if not wb_id:
        op = _log_op("", None, "failed", start_cell_a1=sc["a1"], end_cell_a1=ec["a1"], error_message="Workbook row missing id")
        return _err("NOT_FOUND", "Workbook not found", filepath=fp, operation=op)
    if wb.get("status") != "active":
        op = _log_op(wb_id, None, "failed", start_cell_a1=sc["a1"], end_cell_a1=ec["a1"],
                     error_message=f"Workbook is not writable in its current status ({wb.get('status')})")
        return _err("CONFLICT", "Workbook is not writable in its current status", status=wb.get("status"), workbook_id=wb_id, operation=op)

    # ---- resolve worksheet ----
    worksheets = _load("worksheets.json")
    sn = sheet_name.strip()
    ws = None
    for row in worksheets:
        if isinstance(row, dict) and row.get("workbook_id") == wb_id and row.get("status") == "active" and row.get("name") == sn:
            ws = row
            break
    if ws is None:
        sn_u = sn.upper()
        for row in worksheets:
            if not isinstance(row, dict):
                continue
            if row.get("workbook_id") != wb_id or row.get("status") != "active":
                continue
            nm = row.get("name")
            if isinstance(nm, str) and nm.strip().upper() == sn_u:
                ws = row
                break
    if ws is None:
        op = _log_op(wb_id, None, "failed", start_cell_a1=sc["a1"], end_cell_a1=ec["a1"], error_message="Worksheet not found or not active")
        return _err("NOT_FOUND", "Worksheet not found or not active", sheet_name=sn, workbook_id=wb_id, operation=op)

    ws_id = ws.get("id")

    result_payload = {
        "formatted_range": f"{sc['a1']}:{ec['a1']}",
        "sheet_name": ws.get("name"),
        "format_keys": sorted(list(format_spec.keys())),
        "note": "Offline audit-only formatting; workbook file mutation is not performed by this local datastore backend.",
    }

    # update workbook access timestamps + best-effort file metadata
    wb["last_opened_at"] = now
    wb["updated_at"] = now
    storage_uri = wb.get("storage_uri")
    path = None
    if isinstance(storage_uri, str) and storage_uri.startswith("file://"):
        path = storage_uri[len("file://"):]
    elif isinstance(wb.get("filepath"), str) and wb.get("filepath"):
        path = wb.get("filepath")
    if isinstance(path, str) and path:
        try:
            st = os.stat(path)
            wb["file_size_bytes"] = int(st.st_size)
            wb["last_modified_at"] = datetime.datetime.utcfromtimestamp(st.st_mtime).replace(microsecond=0).isoformat() + "Z"
        except FileNotFoundError:
            pass
        except PermissionError:
            op = _log_op(wb_id, ws_id, "failed", start_cell_a1=sc["a1"], end_cell_a1=ec["a1"],
                         error_message="Workbook file is not accessible for update (permission denied)")
            return _err("CONFLICT", "Workbook file is not accessible for update", operation=op)

    for i, row in enumerate(workbooks):
        if isinstance(row, dict) and row.get("id") == wb_id:
            workbooks[i] = wb
            _save("workbooks.json", workbooks)
            break

    op = _log_op(wb_id, ws_id, "succeeded", start_cell_a1=sc["a1"], end_cell_a1=ec["a1"], result_payload=result_payload)
    return {
        "operation": op,
        "workbook": {"id": wb_id, "filepath": wb.get("filepath"), "status": wb.get("status")},
        "worksheet": {"id": ws_id, "name": ws.get("name"), "status": ws.get("status")},
        "latency_ms": int((time.time() - t0) * 1000),
    }

def read_data_from_excel(filepath, sheet_name, start_cell=None, end_cell=None, preview_only=None, **_extra):
    import json, os, datetime, time, re, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0038000" if __import__("os").path.isdir("./environment_mix/0038000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

    def _new_id(prefix):
        ms = int(time.time() * 1000)
        r = random.getrandbits(80)
        v = (ms << 80) | r
        chars = []
        for _ in range(26):
            chars.append(_B32[v & 31])
            v >>= 5
        return prefix + "".join(reversed(chars))

    _A1_RE = re.compile(r"^\$?([A-Z]{1,3})\$?([1-9][0-9]*)$")

    def _col_to_num(col):
        n = 0
        for ch in col:
            n = n * 26 + (ord(ch) - 64)
        return n

    def _num_to_col(n):
        s = ""
        while n > 0:
            n, r = divmod(n - 1, 26)
            s = chr(65 + r) + s
        return s

    def _parse_a1(addr):
        if not isinstance(addr, str):
            return None
        s = addr.strip().upper().replace("$", "")
        m = _A1_RE.match(s)
        if not m:
            return None
        col_s, row_s = m.group(1), m.group(2)
        col_n = _col_to_num(col_s)
        row_n = int(row_s)
        if not (1 <= col_n <= 16384 and 1 <= row_n <= 1048576):
            return None
        return {"col": col_n, "row": row_n, "a1": f"{col_s}{row_n}"}

    def _rect_ok(a, b):
        return (b["col"] >= a["col"]) and (b["row"] >= a["row"]) and not (a["col"] == b["col"] and a["row"] == b["row"] and False)

    def _resolve_workbook_by_filepath(workbooks, fp):
        cand = [w for w in workbooks if isinstance(w, dict) and w.get("filepath") == fp and w.get("status") != "deleted"]
        if not cand:
            return None
        # Prefer active, else any non-deleted
        for st in ("active", "archived", "creating", "error"):
            for w in cand:
                if w.get("status") == st:
                    return w
        return cand[0]

    def _resolve_worksheet(worksheets, workbook_id, sheet):
        # Try exact active match first
        for ws in worksheets:
            if isinstance(ws, dict) and ws.get("workbook_id") == workbook_id and ws.get("name") == sheet and ws.get("status") == "active":
                return ws
        # Fallback: case-insensitive match among active (vendor often treats sheet names case-insensitively)
        sheet_l = sheet.lower()
        for ws in worksheets:
            if isinstance(ws, dict) and ws.get("workbook_id") == workbook_id and isinstance(ws.get("name"), str) and ws.get("name").lower() == sheet_l and ws.get("status") == "active":
                return ws
        return None

    def _log_operation(status, wb_id, ws_id, sc, ec, preview_flag, params, result_payload=None, error_message=None, started_at=None):
        ops = _load("range_operations.json")
        ts = _now()
        op_id = _new_id("exop_")
        row = {
            "id": op_id,
            "workbook_id": wb_id or "",
            "worksheet_id": ws_id,
            "tool_name": "read_data_from_excel",
            "operation_scope": "range",
            "start_cell": sc,
            "end_cell": ec,
            "source_range": None,
            "destination_start_cell": None,
            "shift_direction": None,
            "formula": None,
            "format_spec": None,
            "write_payload": None,
            "read_preview_only": bool(preview_flag) if preview_flag is not None else None,
            "request_params": params if isinstance(params, dict) else {"raw": params},
            "result_payload": result_payload,
            "error_message": error_message,
            "status": status,
            "started_at": started_at or ts,
            "completed_at": ts if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": ts,
            "updated_at": ts,
        }
        ops.append(row)
        _save("range_operations.json", ops)
        return row

    t0 = time.time()
    started = _now()

    # Validate input types
    if not isinstance(filepath, str) or not filepath.strip():
        op = _log_operation(
            "failed", "", None, None, None, preview_only,
            {"filepath": filepath, "sheet_name": sheet_name, "start_cell": start_cell, "end_cell": end_cell, "preview_only": preview_only},
            error_message="filepath must be a non-empty string"
        )
        return _err("VALIDATION_ERROR", "filepath must be a non-empty string", operation=op)

    if not isinstance(sheet_name, str) or not sheet_name.strip():
        op = _log_operation(
            "failed", "", None, None, None, preview_only,
            {"filepath": filepath, "sheet_name": sheet_name, "start_cell": start_cell, "end_cell": end_cell, "preview_only": preview_only},
            error_message="sheet_name must be a non-empty string"
        )
        return _err("VALIDATION_ERROR", "sheet_name must be a non-empty string", operation=op)

    fp = filepath.strip()
    sh = sheet_name.strip()

    if preview_only is not None and not isinstance(preview_only, bool):
        op = _log_operation(
            "failed", "", None, None, None, preview_only,
            {"filepath": fp, "sheet_name": sh, "start_cell": start_cell, "end_cell": end_cell, "preview_only": preview_only},
            error_message="preview_only must be a boolean when provided"
        )
        return _err("VALIDATION_ERROR", "preview_only must be a boolean when provided", operation=op)

    if start_cell is None:
        start_cell = "A1"
    if not isinstance(start_cell, str) or not start_cell.strip():
        op = _log_operation(
            "failed", "", None, None, None, preview_only,
            {"filepath": fp, "sheet_name": sh, "start_cell": start_cell, "end_cell": end_cell, "preview_only": preview_only},
            error_message="start_cell must be a non-empty string when provided"
        )
        return _err("VALIDATION_ERROR", "start_cell must be a non-empty string when provided", operation=op)

    if end_cell is not None and (not isinstance(end_cell, str) or not end_cell.strip()):
        op = _log_operation(
            "failed", "", None, None, None, preview_only,
            {"filepath": fp, "sheet_name": sh, "start_cell": start_cell, "end_cell": end_cell, "preview_only": preview_only},
            error_message="end_cell must be a non-empty string when provided"
        )
        return _err("VALIDATION_ERROR", "end_cell must be a non-empty string when provided", operation=op)

    sc = _parse_a1(start_cell)
    if not sc:
        op = _log_operation(
            "failed", "", None, start_cell, end_cell, preview_only,
            {"filepath": fp, "sheet_name": sh, "start_cell": start_cell, "end_cell": end_cell, "preview_only": preview_only},
            error_message=f"Invalid A1 reference: {start_cell}"
        )
        return _err("VALIDATION_ERROR", "Invalid start_cell A1 reference", start_cell=start_cell, operation=op)

    ec = None
    if end_cell is not None:
        ec = _parse_a1(end_cell)
        if not ec:
            op = _log_operation(
                "failed", "", None, start_cell, end_cell, preview_only,
                {"filepath": fp, "sheet_name": sh, "start_cell": start_cell, "end_cell": end_cell, "preview_only": preview_only},
                error_message=f"Invalid A1 reference: {end_cell}"
            )
            return _err("VALIDATION_ERROR", "Invalid end_cell A1 reference", end_cell=end_cell, operation=op)
        if not _rect_ok(sc, ec):
            op = _log_operation(
                "failed", "", None, sc["a1"], ec["a1"], preview_only,
                {"filepath": fp, "sheet_name": sh, "start_cell": start_cell, "end_cell": end_cell, "preview_only": preview_only},
                error_message=f"Invalid range: {sc['a1']}:{ec['a1']} (non-empty rectangular ranges only)"
            )
            return _err("VALIDATION_ERROR", "Invalid range (end_cell must be bottom-right of start_cell)", operation=op)

    # Resolve workbook + worksheet
    workbooks = _load("workbooks.json")
    wb = _resolve_workbook_by_filepath(workbooks, fp)
    if not wb:
        op = _log_operation(
            "failed", "", None, sc["a1"], ec["a1"] if ec else None, preview_only,
            {"filepath": fp, "sheet_name": sh, "start_cell": sc["a1"], "end_cell": ec["a1"] if ec else None, "preview_only": preview_only},
            error_message="Workbook not found for filepath (non-deleted)"
        )
        return _err("NOT_FOUND", "Workbook not found", filepath=fp, operation=op)

    wb_id = wb.get("id") or ""
    worksheets = _load("worksheets.json")
    ws = _resolve_worksheet(worksheets, wb_id, sh)
    if not ws:
        op = _log_operation(
            "failed", wb_id, None, sc["a1"], ec["a1"] if ec else None, preview_only,
            {"filepath": fp, "sheet_name": sh, "start_cell": sc["a1"], "end_cell": ec["a1"] if ec else None, "preview_only": preview_only},
            error_message="Worksheet not found or not active"
        )
        return _err("NOT_FOUND", "Worksheet not found or not active", filepath=fp, sheet_name=sh, workbook_id=wb_id, operation=op)

    # Auto-expand end_cell if omitted: use worksheet.dimension_ref if present, else default to start_cell
    resolved_end = ec
    auto_expanded = False
    if resolved_end is None:
        dim = ws.get("dimension_ref")
        if isinstance(dim, str) and ":" in dim:
            a, b = [p.strip() for p in dim.split(":", 1)]
            b_p = _parse_a1(b)
            a_p = _parse_a1(a)
            if a_p and b_p:
                # ensure end is at least start
                r_end = max(sc["row"], b_p["row"])
                c_end = max(sc["col"], b_p["col"])
                resolved_end = {"row": r_end, "col": c_end, "a1": f"{_num_to_col(c_end)}{r_end}"}
                auto_expanded = True
        if resolved_end is None:
            resolved_end = sc
            auto_expanded = True

    # Update workbook last_opened_at/updated_at
    ts = _now()
    for w in workbooks:
        if isinstance(w, dict) and w.get("id") == wb_id:
            w["last_opened_at"] = ts
            w["updated_at"] = ts
            break
    _save("workbooks.json", workbooks)

    # Build a deterministic placeholder result (offline; no Excel engine)
    nrows = max(1, resolved_end["row"] - sc["row"] + 1)
    ncols = max(1, resolved_end["col"] - sc["col"] + 1)
    max_cells = 50 if preview_only else 2000
    cells = []
    count = 0
    for r in range(sc["row"], resolved_end["row"] + 1):
        if count >= max_cells:
            break
        row_vals = []
        for c in range(sc["col"], resolved_end["col"] + 1):
            if count >= max_cells:
                break
            row_vals.append(None)
            count += 1
        cells.append(row_vals)
        if count >= max_cells:
            break

    # Attach cached data validations intersecting the requested range (simple overlap check by bbox parse)
    validations = _load("data_validations.json")
    dvs = []
    def _parse_range_bbox(rng):
        if not isinstance(rng, str) or not rng.strip():
            return None
        s = rng.strip()
        # multi-area => take each part
        parts = [p.strip() for p in s.split(",") if p.strip()]
        out = []
        for part in parts:
            if "!" in part:
                _, part = part.split("!", 1)
                part = part.strip()
            part = part.replace("$", "").upper()
            if ":" in part:
                a, b = [x.strip() for x in part.split(":", 1)]
                pa = _parse_a1(a)
                pb = _parse_a1(b)
                if not pa or not pb:
                    continue
                r1, r2 = sorted([pa["row"], pb["row"]])
                c1, c2 = sorted([pa["col"], pb["col"]])
                out.append((r1, c1, r2, c2))
            else:
                pa = _parse_a1(part)
                if not pa:
                    continue
                out.append((pa["row"], pa["col"], pa["row"], pa["col"]))
        return out or None

    req_box = (sc["row"], sc["col"], resolved_end["row"], resolved_end["col"])
    for dv in validations:
        if not isinstance(dv, dict):
            continue
        if dv.get("workbook_id") != wb_id or dv.get("worksheet_id") != ws.get("id"):
            continue
        if dv.get("status") != "current":
            continue
        boxes = _parse_range_bbox(dv.get("applies_to_range"))
        if not boxes:
            continue
        for (r1, c1, r2, c2) in boxes:
            # overlap check
            if not (r2 < req_box[0] or r1 > req_box[2] or c2 < req_box[1] or c1 > req_box[3]):
                dvs.append(dv)
                break

    result_payload = {
        "workbook_id": wb_id,
        "worksheet_id": ws.get("id"),
        "sheet_name": ws.get("name"),
        "start_cell": sc["a1"],
        "end_cell": resolved_end["a1"],
        "auto_expanded": auto_expanded,
        "returned_cells": {"rows": len(cells), "cols": len(cells[0]) if cells else 0, "truncated": (nrows * ncols) > max_cells},
        "data_validations": ([] if preview_only else dvs),
    }

    op = _log_operation(
        "succeeded",
        wb_id,
        ws.get("id"),
        sc["a1"],
        resolved_end["a1"],
        preview_only,
        {"filepath": fp, "sheet_name": sh, "start_cell": sc["a1"], "end_cell": (end_cell.strip() if isinstance(end_cell, str) else None), "preview_only": preview_only},
        result_payload=result_payload,
        error_message=None,
        started_at=started
    )

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "operation": op,
        "data": {
            "values": cells,
            "range": f"{ws.get('name')}!{sc['a1']}:{resolved_end['a1']}",
            "metadata": ({} if preview_only else {"workbook": wb, "worksheet": ws}),
            "latency_ms": latency_ms,
        },
    }

def write_data_to_excel(filepath, sheet_name, start_cell, data, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0038000" if __import__("os").path.isdir("./environment_mix/0038000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        rnd = int.from_bytes(hashlib.sha256(f"{ms}|{time.time_ns()}".encode("utf-8")).digest()[:10], "big")
        v = (ms << 80) | rnd
        chars = []
        for _ in range(26):
            chars.append(alphabet[v & 31]); v >>= 5
        return prefix + "".join(reversed(chars))

    def _is_nonempty_str(x):
        return isinstance(x, str) and x.strip() != ""

    _CELL_RE = re.compile(r"^\$?([A-Z]{1,3})\$?([1-9][0-9]{0,6})$")
    def _col_to_num(col):
        n = 0
        for ch in col:
            n = n * 26 + (ord(ch) - 64)
        return n

    def _parse_cell(a1):
        if not _is_nonempty_str(a1):
            return None
        s = a1.strip().upper().replace("$", "")
        m = _CELL_RE.fullmatch(s)
        if not m:
            return None
        col_s, row_s = m.group(1), m.group(2)
        c = _col_to_num(col_s)
        r = int(row_s)
        if not (1 <= c <= 16384 and 1 <= r <= 1048576):
            return None
        return (r, c, f"{col_s}{r}")

    def _cell_to_a1(r, c):
        if r < 1 or c < 1:
            return None
        x = c
        letters = []
        while x > 0:
            x, rem = divmod(x - 1, 26)
            letters.append(chr(ord("A") + rem))
        return "".join(reversed(letters)) + str(r)

    def _resolve_workbook_by_filepath(workbooks_rows, fp):
        matches = [w for w in workbooks_rows if isinstance(w, dict) and w.get("filepath") == fp and w.get("status") != "deleted"]
        if len(matches) == 0:
            return None, _err("NOT_FOUND", "Workbook not found for filepath (non-deleted).", filepath=fp)
        if len(matches) > 1:
            return None, _err("CONFLICT", "Multiple workbooks match filepath; expected exactly one non-deleted workbook.", filepath=fp, count=len(matches))
        return matches[0], None

    def _resolve_worksheet_by_name(worksheets_rows, workbook_id, name):
        # IMPORTANT: prefer active worksheet; if only deleted exists, treat as deleted (NOT_FOUND/CONFLICT per rule).
        active = [ws for ws in worksheets_rows if isinstance(ws, dict) and ws.get("workbook_id") == workbook_id and ws.get("name") == name and ws.get("status") == "active"]
        if active:
            return active[0], None
        deleted = [ws for ws in worksheets_rows if isinstance(ws, dict) and ws.get("workbook_id") == workbook_id and ws.get("name") == name and ws.get("status") == "deleted"]
        if deleted:
            return None, _err("CONFLICT", "Worksheet is deleted; write operation rejected.", workbook_id=workbook_id, sheet_name=name, worksheet_id=deleted[0].get("id"))
        return None, _err("NOT_FOUND", "Worksheet not found in workbook (active).", workbook_id=workbook_id, sheet_name=name)

    def _log_op(wb_id, ws_id, status, started_at, completed_at, error_message=None, result_payload=None, write_payload=None):
        ops = _load("range_operations.json")
        ts = _now()
        row = {
            "id": _gen_ulid("exop_"),
            "workbook_id": wb_id or "",
            "worksheet_id": ws_id,
            "tool_name": "write_data_to_excel",
            "operation_scope": "range",
            "start_cell": start_cell if isinstance(start_cell, str) else None,
            "end_cell": None,
            "source_range": None,
            "destination_start_cell": None,
            "shift_direction": None,
            "formula": None,
            "format_spec": None,
            "write_payload": write_payload,
            "read_preview_only": None,
            "request_params": {"filepath": filepath, "sheet_name": sheet_name, "start_cell": start_cell, "data": data},
            "result_payload": result_payload,
            "error_message": error_message,
            "status": status,
            "started_at": started_at,
            "completed_at": completed_at,
            "created_at": ts,
            "updated_at": ts,
        }
        ops.append(row)
        _save("range_operations.json", ops)
        return row

    started_at = _now()

    # Validate inputs
    if not _is_nonempty_str(filepath):
        op = _log_op("", None, "failed", started_at, _now(), error_message="filepath must be a non-empty string.")
        return _err("VALIDATION_ERROR", "filepath must be a non-empty string.", operation_id=op["id"])
    if not _is_nonempty_str(sheet_name):
        op = _log_op("", None, "failed", started_at, _now(), error_message="sheet_name must be a non-empty string.")
        return _err("VALIDATION_ERROR", "sheet_name must be a non-empty string.", operation_id=op["id"])
    sc = _parse_cell(start_cell)
    if not sc:
        op = _log_op("", None, "failed", started_at, _now(), error_message="start_cell must be a valid A1 address.")
        return _err("VALIDATION_ERROR", "start_cell must be a valid A1 address.", operation_id=op["id"], start_cell=start_cell)
    if not isinstance(data, list) or len(data) == 0 or not all(isinstance(r, list) for r in data) or any(len(r) == 0 for r in data):
        op = _log_op("", None, "failed", started_at, _now(), error_message="data must be a non-empty 2D array (row-major).")
        return _err("VALIDATION_ERROR", "data must be a non-empty 2D array (row-major).", operation_id=op["id"])
    # Ensure rectangular
    width = len(data[0])
    if any(len(r) != width for r in data):
        op = _log_op("", None, "failed", started_at, _now(), error_message="data must be a rectangular 2D array (all rows same length).")
        return _err("VALIDATION_ERROR", "data must be a rectangular 2D array (all rows same length).", operation_id=op["id"])

    # Resolve workbook and worksheet
    workbooks = _load("workbooks.json")
    if isinstance(workbooks, dict) and "rows" in workbooks and isinstance(workbooks["rows"], list):
        workbooks_rows = workbooks["rows"]
    else:
        workbooks_rows = workbooks if isinstance(workbooks, list) else []
    wb, e = _resolve_workbook_by_filepath(workbooks_rows, filepath)
    if e:
        op = _log_op("", None, "failed", started_at, _now(), error_message=e["error"]["message"])
        e["error"]["operation_id"] = op["id"]
        return e
    wb_id = wb.get("id")

    worksheets = _load("worksheets.json")
    if isinstance(worksheets, dict) and "rows" in worksheets and isinstance(worksheets["rows"], list):
        worksheets_rows = worksheets["rows"]
    else:
        worksheets_rows = worksheets if isinstance(worksheets, list) else []
    ws, e = _resolve_worksheet_by_name(worksheets_rows, wb_id, sheet_name)
    if e:
        op = _log_op(wb_id, None, "failed", started_at, _now(), error_message=e["error"]["message"])
        e["error"]["operation_id"] = op["id"]
        e["error"]["filepath"] = filepath
        e["error"]["workbook_id"] = wb_id
        e["error"]["sheet_name"] = sheet_name
        return e

    # Enforce workbook state usable for writes
    if wb.get("status") == "deleted":
        op = _log_op(wb_id, ws.get("id"), "failed", started_at, _now(), error_message="Workbook is deleted.")
        return _err("NOT_FOUND", "Workbook is deleted.", operation_id=op["id"], workbook_id=wb_id)
    if wb.get("status") in ("creating", "archived", "error"):
        op = _log_op(wb_id, ws.get("id"), "failed", started_at, _now(), error_message=f"Workbook status '{wb.get('status')}' does not allow write operations.")
        return _err("INVALID_TRANSITION", f"Workbook status '{wb.get('status')}' does not allow write operations.", operation_id=op["id"], workbook_id=wb_id)

    # Simulate persisted write by recording operation and updating workbook hash/timestamps (observable dynamics)
    # Note: no real Excel IO; datastore only. Still must persist effects: operation row + hash/timestamps.
    r0, c0, sc_norm = sc
    rows = len(data)
    cols = width
    r1 = r0 + rows - 1
    c1 = c0 + cols - 1
    end_a1 = _cell_to_a1(r1, c1)

    write_payload = {
        "sheet_name": sheet_name,
        "start_cell": sc_norm,
        "values": data
    }

    # Update workbook "file" fingerprint as if changed.
    completed_at = _now()
    digest = hashlib.sha256(json.dumps(write_payload, ensure_ascii=False, sort_keys=True).encode("utf-8")).hexdigest()
    # If workbook already has a hash, chain it to show evolution
    prior = wb.get("file_hash_sha256") or ""
    new_hash = hashlib.sha256((prior + "|" + digest + "|" + completed_at).encode("utf-8")).hexdigest()

    # Persist workbook updates
    ts = _now()
    for w in workbooks_rows:
        if isinstance(w, dict) and w.get("id") == wb_id:
            w["file_hash_sha256"] = new_hash
            w["last_modified_at"] = completed_at
            w["last_opened_at"] = completed_at
            w["updated_at"] = ts
            break
    # Save back, preserving possible {"rows": ...} wrapper
    if isinstance(workbooks, dict) and "rows" in workbooks and isinstance(workbooks["rows"], list):
        workbooks["rows"] = workbooks_rows
        _save("workbooks.json", workbooks)
    else:
        _save("workbooks.json", workbooks_rows)

    result_payload = {
        "workbook_id": wb_id,
        "worksheet_id": ws.get("id"),
        "sheet_name": sheet_name,
        "written_range": f"{sc_norm}:{end_a1}",
        "start_cell": sc_norm,
        "end_cell": end_a1,
        "rows_written": rows,
        "cols_written": cols,
        "workbook_hash_after": new_hash,
    }
    op = _log_op(wb_id, ws.get("id"), "succeeded", started_at, completed_at, result_payload=result_payload, write_payload=write_payload)

    return {
        "operation": op,
        "summary": result_payload
    }

def create_worksheet(filepath, sheet_name, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0038000" if __import__("os").path.isdir("./environment_mix/0038000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_id(prefix):
        ms = int(time.time() * 1000)
        r = random.getrandbits(80)
        v = (ms << 80) | r
        chars = []
        for _ in range(26):
            chars.append(_B32[v & 31])
            v >>= 5
        return prefix + "".join(reversed(chars))

    def _log(status, wb_id, ws_id=None, error_message=None, result_payload=None):
        ops = _load("range_operations.json")
        op_id = _new_id("exop_")
        row = {
            "id": op_id,
            "workbook_id": wb_id or "",
            "worksheet_id": ws_id,
            "tool_name": "create_worksheet",
            "operation_scope": "worksheet",
            "start_cell": None,
            "end_cell": None,
            "source_range": None,
            "destination_start_cell": None,
            "shift_direction": None,
            "formula": None,
            "format_spec": None,
            "write_payload": None,
            "read_preview_only": None,
            "request_params": {"filepath": filepath, "sheet_name": sheet_name},
            "result_payload": result_payload,
            "error_message": error_message,
            "status": status,
            "started_at": now,
            "completed_at": now,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("range_operations.json", ops)
        return row

    if not isinstance(filepath, str) or not filepath.strip():
        op = _log("failed", "", error_message="filepath must be a non-empty string")
        return _err("VALIDATION_ERROR", "filepath must be a non-empty string", operation=op)
    if not isinstance(sheet_name, str) or not sheet_name.strip():
        op = _log("failed", "", error_message="sheet_name must be a non-empty string")
        return _err("VALIDATION_ERROR", "sheet_name must be a non-empty string", operation=op)

    name = sheet_name.strip()
    if len(name) > 31:
        op = _log("failed", "", error_message="sheet_name must be 31 characters or fewer")
        return _err("VALIDATION_ERROR", "sheet_name must be 31 characters or fewer", operation=op)
    if any(ch in name for ch in ['\\', '/', '*', '?', ':', '[', ']']):
        op = _log("failed", "", error_message="sheet_name contains invalid characters")
        return _err("VALIDATION_ERROR", "sheet_name contains invalid characters", operation=op)
    if name.startswith("'") or name.endswith("'"):
        op = _log("failed", "", error_message="sheet_name must not start or end with an apostrophe")
        return _err("VALIDATION_ERROR", "sheet_name must not start or end with an apostrophe", operation=op)

    workbooks = _load("workbooks.json")
    fp = filepath.strip()
    cands = [w for w in workbooks if isinstance(w, dict) and w.get("filepath") == fp and w.get("status") != "deleted"]
    if not cands:
        op = _log("failed", "", error_message="Workbook not found for filepath")
        return _err("NOT_FOUND", "Workbook not found", filepath=fp, operation=op)

    def _rank_wb(w):
        return {"active": 0, "archived": 1, "error": 2, "creating": 3}.get(w.get("status"), 9)
    cands.sort(key=_rank_wb)
    wb = cands[0]
    wb_id = wb.get("id") or ""
    if not wb_id:
        op = _log("failed", "", error_message="Workbook row missing id")
        return _err("NOT_FOUND", "Workbook not found", filepath=fp, operation=op)
    if wb.get("status") != "active":
        op = _log("failed", wb_id, error_message=f"Workbook is not writable in its current status ({wb.get('status')})")
        return _err("CONFLICT", "Workbook is not writable in its current status", status=wb.get("status"), workbook_id=wb_id, operation=op)

    worksheets = _load("worksheets.json")
    for s in worksheets:
        if isinstance(s, dict) and s.get("workbook_id") == wb_id and s.get("status") == "active" and s.get("name") == name:
            op = _log("failed", wb_id, error_message=f"Worksheet name '{name}' already exists in this workbook")
            return _err("CONFLICT", "Worksheet with the same name already exists", sheet_name=name, workbook_id=wb_id, operation=op)

    ws_id = _new_id("exws_")
    ws = {
        "id": ws_id,
        "workbook_id": wb_id,
        "name": name,
        "position_index": None,
        "visibility": "visible",
        "status": "active",
        "dimension_ref": None,
        "created_at": now,
        "updated_at": now,
    }
    worksheets.append(ws)
    _save("worksheets.json", worksheets)

    # update workbook timestamps
    for i, row in enumerate(workbooks):
        if isinstance(row, dict) and row.get("id") == wb_id:
            workbooks[i]["updated_at"] = now
            workbooks[i]["last_opened_at"] = now
            _save("workbooks.json", workbooks)
            break

    op = _log("succeeded", wb_id, ws_id=ws_id, result_payload={"worksheet_id": ws_id, "sheet_name": name})
    return {"worksheet": ws, "operation": op, "latency_ms": int((time.time() - t0) * 1000)}

def create_chart(filepath, sheet_name, source_range, anchor_cell, config, **_extra):
    import json, os, datetime, time, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0038000" if __import__("os").path.isdir("./environment_mix/0038000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_id(prefix):
        ms = int(time.time() * 1000)
        r = random.getrandbits(80)
        v = (ms << 80) | r
        chars = []
        for _ in range(26):
            chars.append(_B32[v & 31])
            v >>= 5
        return prefix + "".join(reversed(chars))

    _CELL_RE = re.compile(r"^\$?([A-Z]{1,3})\$?([1-9][0-9]*)$")
    def _parse_cell(a1):
        if not isinstance(a1, str) or not a1.strip():
            return None
        s = a1.strip().upper().replace("$", "")
        m = _CELL_RE.match(s)
        if not m:
            return None
        col_s, row_s = m.group(1), m.group(2)
        col = 0
        for ch in col_s:
            col = col * 26 + (ord(ch) - ord("A") + 1)
        row = int(row_s)
        if not (1 <= col <= 16384 and 1 <= row <= 1048576):
            return None
        return (row, col, f"{col_s}{row}")

    def _parse_range(rng):
        if not isinstance(rng, str) or not rng.strip():
            return None
        s = rng.strip()
        if "!" in s:
            _, s = s.split("!", 1)
            s = s.strip()
        s = s.replace("$", "").upper()
        if ":" in s:
            a, b = [p.strip() for p in s.split(":", 1)]
            p1 = _parse_cell(a)
            p2 = _parse_cell(b)
            if not p1 or not p2:
                return None
            r1, c1, _ = p1
            r2, c2, _ = p2
            rmin, rmax = (r1, r2) if r1 <= r2 else (r2, r1)
            cmin, cmax = (c1, c2) if c1 <= c2 else (c2, c1)
            if rmin == rmax and cmin == cmax:
                # single cell range is allowed, but usually meaningless; still accept
                return (rmin, cmin, rmax, cmax)
            return (rmin, cmin, rmax, cmax)
        p = _parse_cell(s)
        if not p:
            return None
        r, c, _ = p
        return (r, c, r, c)

    def _resolve_workbook_by_filepath(workbooks, fp):
        cand = [w for w in workbooks if isinstance(w, dict) and w.get("filepath") == fp and w.get("status") != "deleted"]
        if not cand:
            return None
        for st in ("active", "archived", "creating", "error"):
            for w in cand:
                if w.get("status") == st:
                    return w
        return cand[0]

    def _resolve_worksheet(worksheets, workbook_id, name):
        for ws in worksheets:
            if isinstance(ws, dict) and ws.get("workbook_id") == workbook_id and ws.get("name") == name and ws.get("status") == "active":
                return ws
        name_l = name.lower()
        for ws in worksheets:
            if isinstance(ws, dict) and ws.get("workbook_id") == workbook_id and isinstance(ws.get("name"), str) and ws.get("name").lower() == name_l and ws.get("status") == "active":
                return ws
        return None

    def _log(status, wb_id, ws_id=None, obj_id=None, error_message=None, result_payload=None, started_at=None, sr=None, ac=None):
        ops = _load("range_operations.json")
        ts = _now()
        op_id = _new_id("exop_")
        row = {
            "id": op_id,
            "workbook_id": wb_id or "",
            "worksheet_id": ws_id,
            "tool_name": "create_chart",
            "operation_scope": "worksheet",
            "start_cell": None,
            "end_cell": None,
            "source_range": sr,
            "destination_start_cell": ac,
            "shift_direction": None,
            "formula": None,
            "format_spec": None,
            "write_payload": None,
            "read_preview_only": None,
            "request_params": {"filepath": filepath, "sheet_name": sheet_name, "source_range": source_range, "anchor_cell": anchor_cell, "config": config},
            "result_payload": result_payload,
            "error_message": error_message,
            "status": status,
            "started_at": started_at or ts,
            "completed_at": ts if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": ts,
            "updated_at": ts,
        }
        ops.append(row)
        _save("range_operations.json", ops)
        return row

    started = _now()
    # Validate
    if not isinstance(filepath, str) or not filepath.strip():
        op = _log("failed", "", error_message="filepath must be a non-empty string", started_at=started)
        return _err("VALIDATION_ERROR", "filepath must be a non-empty string", operation=op)
    if not isinstance(sheet_name, str) or not sheet_name.strip():
        op = _log("failed", "", error_message="sheet_name must be a non-empty string", started_at=started)
        return _err("VALIDATION_ERROR", "sheet_name must be a non-empty string", operation=op)
    if not isinstance(source_range, str) or not source_range.strip():
        op = _log("failed", "", error_message="source_range must be a non-empty string", started_at=started)
        return _err("VALIDATION_ERROR", "source_range must be a non-empty string", operation=op)
    if not isinstance(anchor_cell, str) or not anchor_cell.strip():
        op = _log("failed", "", error_message="anchor_cell must be a non-empty string", started_at=started)
        return _err("VALIDATION_ERROR", "anchor_cell must be a non-empty string", operation=op)
    if not isinstance(config, dict):
        op = _log("failed", "", error_message="config must be an object", started_at=started)
        return _err("VALIDATION_ERROR", "config must be an object", operation=op)

    sr = _parse_range(source_range)
    if not sr:
        op = _log("failed", "", error_message="Invalid A1 range for source_range", started_at=started, sr=source_range, ac=anchor_cell)
        return _err("VALIDATION_ERROR", "Invalid A1 range for source_range", source_range=source_range, operation=op)
    ac = _parse_cell(anchor_cell)
    if not ac:
        op = _log("failed", "", error_message="Invalid A1 reference for anchor_cell", started_at=started, sr=source_range, ac=anchor_cell)
        return _err("VALIDATION_ERROR", "Invalid A1 reference for anchor_cell", anchor_cell=anchor_cell, operation=op)

    fp = filepath.strip()
    sh = sheet_name.strip()
    workbooks = _load("workbooks.json")
    wb = _resolve_workbook_by_filepath(workbooks, fp)
    if not wb:
        op = _log("failed", "", error_message="Workbook not found", started_at=started, sr=source_range, ac=anchor_cell)
        return _err("NOT_FOUND", "Workbook not found", filepath=fp, operation=op)
    wb_id = wb.get("id") or ""

    worksheets = _load("worksheets.json")
    ws = _resolve_worksheet(worksheets, wb_id, sh)
    if not ws:
        op = _log("failed", wb_id, None, error_message="Worksheet not found or not active", started_at=started, sr=source_range, ac=anchor_cell)
        return _err("NOT_FOUND", "Worksheet not found or not active", workbook_id=wb_id, sheet_name=sh, operation=op)

    # Create worksheet_objects row with creating -> active (offline assume confirmation success)
    objects = _load("worksheet_objects.json")
    obj_id = _new_id("exob_")
    ts = _now()
    obj = {
        "id": obj_id,
        "workbook_id": wb_id,
        "worksheet_id": ws.get("id"),
        "object_type": "chart",
        "name": config.get("name") if isinstance(config.get("name"), str) and config.get("name").strip() else None,
        "source_range": source_range,
        "anchor_cell": anchor_cell,
        "config": config,
        "status": "creating",
        "created_at": ts,
        "updated_at": ts,
    }
    # uniqueness: unique(worksheet_id, object_type, name) WHERE name IS NOT NULL AND status='active'
    if obj["name"]:
        for o in objects:
            if isinstance(o, dict) and o.get("worksheet_id") == obj["worksheet_id"] and o.get("object_type") == "chart" and o.get("status") == "active" and o.get("name") == obj["name"]:
                op = _log("failed", wb_id, ws.get("id"), None, error_message=f"Object name '{obj['name']}' already exists", started_at=started, sr=source_range, ac=anchor_cell)
                return _err("CONFLICT", "Chart name already exists on worksheet", name=obj["name"], operation=op)

    objects.append(obj)
    _save("worksheet_objects.json", objects)

    # Transition to active (assume success)
    ts2 = _now()
    for o in objects:
        if isinstance(o, dict) and o.get("id") == obj_id:
            o["status"] = "active"
            o["updated_at"] = ts2
            obj = o
            break
    _save("worksheet_objects.json", objects)

    op = _log("succeeded", wb_id, ws.get("id"), obj_id=obj_id, result_payload={"object_id": obj_id, "object": obj}, started_at=started, sr=source_range, ac=anchor_cell)
    return {"operation": op, "chart": obj}

def create_pivot_table(workbook_id, worksheet_id, name, source_range, anchor_cell, config, **_extra):
    import json, os, datetime, time, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0038000" if __import__("os").path.isdir("./environment_mix/0038000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _ULID_WB = re.compile(r"^exwb_[0-9A-HJKMNP-TV-Z]{26}$")
    _ULID_WS = re.compile(r"^exws_[0-9A-HJKMNP-TV-Z]{26}$")

    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_id(prefix):
        ms = int(time.time() * 1000)
        r = random.getrandbits(80)
        v = (ms << 80) | r
        chars = []
        for _ in range(26):
            chars.append(_B32[v & 31])
            v >>= 5
        return prefix + "".join(reversed(chars))

    def _parse_a1_cell(cell):
        if not isinstance(cell, str) or not cell.strip():
            return None
        s = cell.strip().upper().replace("$", "")
        m = re.fullmatch(r"([A-Z]{1,3})([1-9][0-9]*)", s)
        if not m:
            return None
        col_s, row_s = m.group(1), m.group(2)
        col = 0
        for ch in col_s:
            col = col * 26 + (ord(ch) - ord("A") + 1)
        row = int(row_s)
        if not (1 <= col <= 16384 and 1 <= row <= 1048576):
            return None
        return (row, col, f"{col_s}{row}")

    def _parse_a1_range(rng):
        if not isinstance(rng, str) or not rng.strip():
            return None
        s = rng.strip()
        if "!" in s:
            _, s = s.split("!", 1)
            s = s.strip()
        s = s.upper().replace("$", "")
        if ":" in s:
            a, b = [p.strip() for p in s.split(":", 1)]
            p1 = _parse_a1_cell(a)
            p2 = _parse_a1_cell(b)
            if not p1 or not p2:
                return None
            r1, c1, _ = p1
            r2, c2, _ = p2
            rmin, rmax = (r1, r2) if r1 <= r2 else (r2, r1)
            cmin, cmax = (c1, c2) if c1 <= c2 else (c2, c1)
            return (rmin, cmin, rmax, cmax)
        p = _parse_a1_cell(s)
        if not p:
            return None
        r, c, _ = p
        return (r, c, r, c)

    def _log(status, wb_id, ws_id=None, error_message=None, result_payload=None, started_at=None):
        ops = _load("range_operations.json")
        ts = _now()
        op_id = _new_id("exop_")
        row = {
            "id": op_id,
            "workbook_id": wb_id or "",
            "worksheet_id": ws_id,
            "tool_name": "create_pivot_table",
            "operation_scope": "worksheet",
            "start_cell": None,
            "end_cell": None,
            "source_range": source_range,
            "destination_start_cell": anchor_cell,
            "shift_direction": None,
            "formula": None,
            "format_spec": None,
            "write_payload": None,
            "read_preview_only": None,
            "request_params": {"workbook_id": workbook_id, "worksheet_id": worksheet_id, "name": name, "source_range": source_range, "anchor_cell": anchor_cell, "config": config},
            "result_payload": result_payload,
            "error_message": error_message,
            "status": status,
            "started_at": started_at or ts,
            "completed_at": ts if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": ts,
            "updated_at": ts,
        }
        ops.append(row)
        _save("range_operations.json", ops)
        return row

    started = _now()
    if not isinstance(workbook_id, str) or not _ULID_WB.match(workbook_id):
        op = _log("failed", "", error_message="workbook_id is malformed; expected ULID exwb_...", started_at=started)
        return _err("VALIDATION_ERROR", "workbook_id is malformed; expected ULID exwb_...", operation=op)
    if not isinstance(worksheet_id, str) or not _ULID_WS.match(worksheet_id):
        op = _log("failed", workbook_id, error_message="worksheet_id is malformed; expected ULID exws_...", started_at=started)
        return _err("VALIDATION_ERROR", "worksheet_id is malformed; expected ULID exws_...", operation=op)
    if not isinstance(name, str) or not name.strip():
        op = _log("failed", workbook_id, worksheet_id, error_message="name must be a non-empty string", started_at=started)
        return _err("VALIDATION_ERROR", "name must be a non-empty string", operation=op)
    if not isinstance(source_range, str) or not source_range.strip() or not _parse_a1_range(source_range):
