def create_table(workbook_id, worksheet_id, name, source_range, anchor_cell=None, config=None, **_extra):
    import json, os, datetime, time, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0038000" if __import__("os").path.isdir("./environment_mix/0038000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _ULID_WB = re.compile(r"^exwb_[0-9A-HJKMNP-TV-Z]{26}$")
    _ULID_WS = re.compile(r"^exws_[0-9A-HJKMNP-TV-Z]{26}$")

    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_id(prefix):
        ms = int(time.time() * 1000)
        r = random.getrandbits(80)
        v = (ms << 80) | r
        chars = []
        for _ in range(26):
            chars.append(_B32[v & 31])
            v >>= 5
        return prefix + "".join(reversed(chars))

    def _parse_a1_cell(cell):
        if cell is None:
            return None
        if not isinstance(cell, str) or not cell.strip():
            return None
        s = cell.strip().upper().replace("$", "")
        m = re.fullmatch(r"([A-Z]{1,3})([1-9][0-9]*)", s)
        if not m:
            return None
        col_s, row_s = m.group(1), m.group(2)
        col = 0
        for ch in col_s:
            col = col * 26 + (ord(ch) - ord("A") + 1)
        row = int(row_s)
        if not (1 <= col <= 16384 and 1 <= row <= 1048576):
            return None
        return (row, col, f"{col_s}{row}")

    def _parse_a1_range(rng):
        if not isinstance(rng, str) or not rng.strip():
            return None
        s = rng.strip()
        if "!" in s:
            _, s = s.split("!", 1)
            s = s.strip()
        s = s.upper().replace("$", "")
        if ":" in s:
            a, b = [p.strip() for p in s.split(":", 1)]
            p1 = _parse_a1_cell(a)
            p2 = _parse_a1_cell(b)
            if not p1 or not p2:
                return None
            r1, c1, _ = p1
            r2, c2, _ = p2
            rmin, rmax = (r1, r2) if r1 <= r2 else (r2, r1)
            cmin, cmax = (c1, c2) if c1 <= c2 else (c2, c1)
            return (rmin, cmin, rmax, cmax)
        p = _parse_a1_cell(s)
        if not p:
            return None
        r, c, _ = p
        return (r, c, r, c)

    def _log(status, wb_id, ws_id=None, error_message=None, result_payload=None, started_at=None):
        ops = _load("range_operations.json")
        ts = _now()
        op_id = _new_id("exop_")
