            "error_message": error_message,
            "status": status,
            "started_at": started_at or ts,
            "completed_at": ts if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": ts,
            "updated_at": ts,
        }
        ops.append(row)
        _save("range_operations.json", ops)
        return row

    started = _now()
    if not isinstance(workbook_id, str) or not _ULID_WB.match(workbook_id):
        op = _log("failed", "", error_message="workbook_id is malformed; expected ULID exwb_...", started_at=started)
        return _err("VALIDATION_ERROR", "workbook_id is malformed; expected ULID exwb_...", operation=op)
    if not isinstance(worksheet_id, str) or not _ULID_WS.match(worksheet_id):
        op = _log("failed", workbook_id, error_message="worksheet_id is malformed; expected ULID exws_...", started_at=started)
        return _err("VALIDATION_ERROR", "worksheet_id is malformed; expected ULID exws_...", operation=op)
    if not isinstance(name, str) or not name.strip():
        op = _log("failed", workbook_id, worksheet_id, error_message="name must be a non-empty string", started_at=started)
        return _err("VALIDATION_ERROR", "name must be a non-empty string", operation=op)
    if not isinstance(source_range, str) or not source_range.strip() or not _parse_a1_range(source_range):
        op = _log("failed", workbook_id, worksheet_id, error_message="source_range must be a valid A1-style range", started_at=started)
        return _err("VALIDATION_ERROR", "source_range must be a valid A1-style range", operation=op)
    if anchor_cell is not None and (not isinstance(anchor_cell, str) or not anchor_cell.strip() or not _parse_a1_cell(anchor_cell)):
        op = _log("failed", workbook_id, worksheet_id, error_message="anchor_cell must be a valid A1-style cell when provided", started_at=started)
        return _err("VALIDATION_ERROR", "anchor_cell must be a valid A1-style cell when provided", operation=op)
    if config is not None and not isinstance(config, dict):
        op = _log("failed", workbook_id, worksheet_id, error_message="config must be an object when provided", started_at=started)
        return _err("VALIDATION_ERROR", "config must be an object when provided", operation=op)

    workbooks = _load("workbooks.json")
