    if not wb:
        op = _log("failed", workbook_id, worksheet_id, error_message="Workbook not found", started_at=started)
        return _err("NOT_FOUND", "Workbook not found", workbook_id=workbook_id, operation=op)

    worksheets = _load("worksheets.json")
