        "config": config,
        "status": "creating",
        "created_at": ts,
        "updated_at": ts,
    }

    # uniqueness for active named objects
    for o in objects:
        if isinstance(o, dict) and o.get("worksheet_id") == worksheet_id and o.get("object_type") == "table" and o.get("status") == "active" and o.get("name") == obj["name"]:
            op = _log("failed", workbook_id, worksheet_id, error_message=f"Object name '{obj['name']}' already exists", started_at=started)
            return _err("CONFLICT", "Table name already exists on worksheet", name=obj["name"], operation=op)

    objects.append(obj)
    _save("worksheet_objects.json", objects)

    # Transition to active (assume success)
    ts2 = _now()
    for o in objects:
        if isinstance(o, dict) and o.get("id") == obj_id:
