def delete_worksheet(workbook_id, worksheet_id, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0038000" if __import__("os").path.isdir("./environment_mix/0038000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _ULID_WB = re.compile(r"^exwb_[0-9A-HJKMNP-TV-Z]{26}$")
    _ULID_WS = re.compile(r"^exws_[0-9A-HJKMNP-TV-Z]{26}$")
    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

    def _new_id(prefix):
        ms = int(time.time() * 1000)
        r = random.getrandbits(80)
        v = (ms << 80) | r
        chars = []
        for _ in range(26):
            chars.append(_B32[v & 31])
            v >>= 5
        return prefix + "".join(reversed(chars))

    workbooks = _load("workbooks.json")
    worksheets = _load("worksheets.json")
    operations = _load("range_operations.json")

    if not isinstance(workbook_id, str) or not _ULID_WB.match(workbook_id):
        return _err("VALIDATION_ERROR", "workbook_id is malformed; expected ULID exwb_...", field="workbook_id")
    if not isinstance(worksheet_id, str) or not _ULID_WS.match(worksheet_id):
        return _err("VALIDATION_ERROR", "worksheet_id is malformed; expected ULID exws_...", field="worksheet_id")

    wb = next((r for r in workbooks if r.get("id") == workbook_id and r.get("status") != "deleted"), None)
    if not wb:
        return _err("NOT_FOUND", "Workbook not found", workbook_id=workbook_id)

    ws = next((r for r in worksheets if r.get("id") == worksheet_id and r.get("workbook_id") == workbook_id), None)
    if not ws:
        return _err("NOT_FOUND", "Worksheet not found in workbook", workbook_id=workbook_id, worksheet_id=worksheet_id)

    if wb.get("status") not in ("active", "archived", "error"):
        return _err("CONFLICT", "Workbook state does not allow worksheet deletion", workbook_status=wb.get("status"))

    if ws.get("status") == "deleted":
        return _err("NOT_FOUND", "Worksheet is already deleted", worksheet_id=worksheet_id)

    # Create range_operation audit (queued->running->succeeded)
    op_id = _new_id("exop_")
    op = {
        "id": op_id,
        "workbook_id": workbook_id,
        "worksheet_id": worksheet_id,
        "tool_name": "delete_worksheet",
        "operation_scope": "worksheet",
        "start_cell": None,
        "end_cell": None,
        "source_range": None,
        "destination_start_cell": None,
        "shift_direction": None,
        "formula": None,
        "format_spec": None,
        "write_payload": None,
        "read_preview_only": None,
        "request_params": {
            "workbook_id": workbook_id,
            "worksheet_id": worksheet_id
        },
        "result_payload": None,
        "error_message": None,
        "status": "queued",
        "started_at": None,
        "completed_at": None,
        "created_at": now,
        "updated_at": now
    }
    operations.append(op)
    _save("range_operations.json", operations)

    op["status"] = "running"
    op["started_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    op["updated_at"] = op["started_at"]
    _save("range_operations.json", operations)

    # Transition worksheet active -> deleted
    ws["status"] = "deleted"
    ws["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _save("worksheets.json", worksheets)

    op["status"] = "succeeded"
    op["result_payload"] = {"deleted_worksheet_id": worksheet_id, "name": ws.get("name")}
    op["completed_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    op["updated_at"] = op["completed_at"]
    _save("range_operations.json", operations)

    return {
        "deleted_worksheet": {
            "id": worksheet_id,
            "workbook_id": workbook_id,
            "name": ws.get("name"),
            "status": "deleted"
        },
        "operation": op,
        "latency_ms": int((time.time() - t0) * 1000)
    }

def rename_worksheet(workbook_id, worksheet_id, new_name, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0038000" if __import__("os").path.isdir("./environment_mix/0038000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}
    def _now(): return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _ULID_WB = re.compile(r"^exwb_[0-9A-HJKMNP-TV-Z]{26}$")
    _ULID_WS = re.compile(r"^exws_[0-9A-HJKMNP-TV-Z]{26}$")
    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

    def _new_id(prefix):
        ms = int(time.time() * 1000)
        r = random.getrandbits(80)
        v = (ms << 80) | r
        chars = []
        for _ in range(26):
            chars.append(_B32[v & 31]); v >>= 5
        return prefix + "".join(reversed(chars))

    def _log_call(wb_id, ws_id, params, status, result_payload=None, error_message=None, started_at=None):
        ops = _load("range_operations.json")
        ts = _now()
        op_id = _new_id("exop_")
        row = {
            "id": op_id,
            "workbook_id": wb_id or "",
            "worksheet_id": ws_id,
            "tool_name": "rename_worksheet",
            "operation_scope": "worksheet",
            "start_cell": None,
            "end_cell": None,
            "source_range": None,
            "destination_start_cell": None,
            "shift_direction": None,
            "formula": None,
            "format_spec": None,
            "write_payload": None,
            "read_preview_only": None,
            "request_params": params if isinstance(params, dict) else {"raw": params},
            "result_payload": result_payload,
            "error_message": error_message,
            "status": status,
            "started_at": started_at or ts,
            "completed_at": ts if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": ts,
            "updated_at": ts,
        }
        ops.append(row); _save("range_operations.json", ops)
        return row

    started = _now()
    params = {"workbook_id": workbook_id, "worksheet_id": worksheet_id, "new_name": new_name}

    if not isinstance(workbook_id, str) or not _ULID_WB.match(workbook_id):
        op = _log_call("", worksheet_id if isinstance(worksheet_id, str) else None, params, "failed", error_message="workbook_id is malformed.", started_at=started)
        return _err("VALIDATION_ERROR", "workbook_id is malformed.", operation_id=op["id"], workbook_id=workbook_id)
    if not isinstance(worksheet_id, str) or not _ULID_WS.match(worksheet_id):
        op = _log_call(workbook_id, None, params, "failed", error_message="worksheet_id is malformed.", started_at=started)
        return _err("VALIDATION_ERROR", "worksheet_id is malformed.", operation_id=op["id"], workbook_id=workbook_id, worksheet_id=worksheet_id)
    if not isinstance(new_name, str) or new_name.strip() == "":
        op = _log_call(workbook_id, worksheet_id, params, "failed", error_message="new_name must be a non-empty string.", started_at=started)
        return _err("VALIDATION_ERROR", "new_name must be a non-empty string.", operation_id=op["id"])
    new_name = new_name.strip()

    wbs = _load("workbooks.json")
    wbs_rows = wbs["rows"] if isinstance(wbs, dict) and isinstance(wbs.get("rows"), list) else (wbs if isinstance(wbs, list) else [])
    wb = next((w for w in wbs_rows if isinstance(w, dict) and w.get("id") == workbook_id and w.get("status") != "deleted"), None)
    if not wb:
        op = _log_call(workbook_id, worksheet_id, params, "failed", error_message="Workbook not found (non-deleted).", started_at=started)
        return _err("NOT_FOUND", "Workbook not found (non-deleted).", operation_id=op["id"], workbook_id=workbook_id)

    wss = _load("worksheets.json")
    wss_rows = wss["rows"] if isinstance(wss, dict) and isinstance(wss.get("rows"), list) else (wss if isinstance(wss, list) else [])

    ws = next((x for x in wss_rows if isinstance(x, dict) and x.get("id") == worksheet_id and x.get("workbook_id") == workbook_id), None)
    if not ws:
        op = _log_call(workbook_id, worksheet_id, params, "failed", error_message="Worksheet not found in workbook.", started_at=started)
        return _err("NOT_FOUND", "Worksheet not found in workbook.", operation_id=op["id"], workbook_id=workbook_id, worksheet_id=worksheet_id)
    if ws.get("status") != "active":
        op = _log_call(workbook_id, worksheet_id, params, "failed", error_message="Worksheet is deleted; cannot rename.", started_at=started)
        return _err("CONFLICT", "Worksheet is deleted; cannot rename.", operation_id=op["id"], worksheet_id=worksheet_id)

    # Idempotent: renaming to same name succeeds with no other changes
    if ws.get("name") == new_name:
        result_payload = {"worksheet": ws, "idempotent": True}
        op = _log_call(workbook_id, worksheet_id, params, "succeeded", result_payload=result_payload, started_at=started)
        return {"operation": op, "worksheet": ws}

    collision = next((x for x in wss_rows if isinstance(x, dict) and x.get("workbook_id") == workbook_id and x.get("status") == "active" and x.get("name") == new_name and x.get("id") != worksheet_id), None)
    if collision:
        op = _log_call(workbook_id, worksheet_id, params, "failed", error_message=f"Worksheet name '{new_name}' already exists in this workbook.", started_at=started)
        return _err("CONFLICT", f"Worksheet name '{new_name}' already exists in this workbook.", operation_id=op["id"], workbook_id=workbook_id, new_name=new_name, conflicting_worksheet_id=collision.get("id"))

    ts = _now()
    ws["name"] = new_name
    ws["updated_at"] = ts

    if isinstance(wss, dict) and isinstance(wss.get("rows"), list):
        wss["rows"] = wss_rows
        _save("worksheets.json", wss)
    else:
        _save("worksheets.json", wss_rows)

    result_payload = {"worksheet": ws}
    op = _log_call(workbook_id, worksheet_id, params, "succeeded", result_payload=result_payload, started_at=started)
    return {"operation": op, "worksheet": ws}

def get_workbook_metadata(workbook_id, include_worksheets=None, include_objects=None, **_extra):
    import json, os, datetime, time, random

