        if not isinstance(s, str):
            return False
        if not s.startswith(prefix + "_"):
            return False
        tail = s[len(prefix) + 1 :]
        if len(tail) != 26:
            return False
        for ch in tail:
            if ch not in _CROCK:
                return False
        return True

    def _new_id(prefix):
        t = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(_CROCK[t & 31])
            t >>= 5
        for _ in range(16):
            out.append(_CROCK[random.getrandbits(5)])
        return prefix + "_" + "".join(reversed(out[:10])) + "".join(out[10:])

    def _log_call(tool, wb_id, ws_id, params, status, result_payload=None, error_message=None, started_at=None):
        ops = _load("range_operations.json")
        ts = _now()
        op_id = _new_id("exop")
        row = {
            "id": op_id,
            "workbook_id": wb_id,
            "worksheet_id": ws_id,
            "tool_name": tool,
            "operation_scope": "workbook",
            "start_cell": None,
            "end_cell": None,
            "source_range": None,
            "destination_start_cell": None,
            "shift_direction": None,
            "formula": None,
            "format_spec": None,
            "write_payload": None,
            "read_preview_only": None,
            "request_params": params if isinstance(params, dict) else {"raw": params},
            "result_payload": result_payload,
            "error_message": error_message,
            "status": status,
            "started_at": started_at,
            "completed_at": ts if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": ts,
            "updated_at": ts,
        }
        ops.append(row)
        _save("range_operations.json", ops)
        return row

    if include_worksheets is None:
        include_worksheets = True
    if include_objects is None:
        include_objects = False
    if not isinstance(include_worksheets, bool) or not isinstance(include_objects, bool):
        op = _log_call(
            "get_workbook_metadata",
            workbook_id if isinstance(workbook_id, str) else "exwb_INVALID",
            None,
            {"workbook_id": workbook_id, "include_worksheets": include_worksheets, "include_objects": include_objects},
            "failed",
            error_message="include_worksheets/include_objects must be boolean.",
            started_at=_now(),
        )
        return _err("VALIDATION_ERROR", "include_worksheets/include_objects must be boolean", operation=op)

    if not _ulid_like("exwb", workbook_id):
        op = _log_call(
            "get_workbook_metadata",
            workbook_id if isinstance(workbook_id, str) else "exwb_INVALID",
            None,
            {"workbook_id": workbook_id, "include_worksheets": include_worksheets, "include_objects": include_objects},
            "failed",
            error_message="Malformed workbook_id.",
            started_at=_now(),
        )
        return _err("VALIDATION_ERROR", "workbook_id is malformed", operation=op)

    started_at = _now()
    wbs = _load("workbooks.json")
    wb = None
    for r in wbs:
        if r.get("id") == workbook_id and r.get("status") != "deleted":
            wb = r
            break
    if wb is None:
        op = _log_call(
            "get_workbook_metadata",
            workbook_id,
            None,
            {"workbook_id": workbook_id, "include_worksheets": include_worksheets, "include_objects": include_objects},
            "failed",
            error_message="Workbook not found.",
            started_at=started_at,
        )
        return _err("NOT_FOUND", "workbook not found", operation=op)

    # Opportunistically refresh dimension_ref when workbook hash changed.
    # With no real Excel engine here, we mark unknown dimensions as None, and if hash changed we clear cached refs
    # so downstream tools can observe cache invalidation dynamics.
    wss = _load("worksheets.json")
    hash_now = wb.get("file_hash_sha256")
    refreshed = False
    if include_worksheets:
        for s in wss:
            if s.get("workbook_id") == workbook_id and s.get("status") == "active":
                # If workbook hash changed and a dimension_ref exists, mark it as needing refresh by clearing.
                if hash_now and s.get("dimension_ref") and s.get("updated_at") and wb.get("updated_at"):
                    # Conservative: if workbook updated_at >= sheet updated_at, invalidate cache.
                    try:
                        # Compare ISO-ish strings lexicographically (works for Z timestamps here)
                        if wb.get("updated_at") >= s.get("updated_at"):
                            s["dimension_ref"] = None
                            s["updated_at"] = _now()
                            refreshed = True
                    except Exception:
                        pass

    if refreshed:
        wb["updated_at"] = _now()
        _save("worksheets.json", wss)
        _save("workbooks.json", wbs)

    resp = {"workbook": wb}
    active_sheets = []
    if include_worksheets:
        for s in wss:
            if s.get("workbook_id") == workbook_id and s.get("status") == "active":
                active_sheets.append(s)
        resp["worksheets"] = active_sheets

    if include_objects:
        objs = _load("worksheet_objects.json")
        active_objs = [o for o in objs if o.get("workbook_id") == workbook_id and o.get("status") == "active"]
        resp["objects"] = active_objs

    op = _log_call(
        "get_workbook_metadata",
        workbook_id,
        None,
        {"workbook_id": workbook_id, "include_worksheets": include_worksheets, "include_objects": include_objects},
        "succeeded",
        result_payload={
            "worksheet_count": len(active_sheets) if include_worksheets else None,
            "object_count": len(resp.get("objects", [])) if include_objects else None,
            "refreshed_dimensions": bool(refreshed),
        },
        started_at=started_at,
    )
    resp["operation"] = op
    return resp

def merge_cells(workbook_id, worksheet_id, start_cell, end_cell, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0038000" if __import__("os").path.isdir("./environment_mix/0038000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}
    def _now(): return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _ULID_WB = re.compile(r"^exwb_[0-9A-HJKMNP-TV-Z]{26}$")
    _ULID_WS = re.compile(r"^exws_[0-9A-HJKMNP-TV-Z]{26}$")
    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

    def _new_id(prefix):
        ms = int(time.time() * 1000)
        r = random.getrandbits(80)
        v = (ms << 80) | r
        chars = []
        for _ in range(26):
            chars.append(_B32[v & 31]); v >>= 5
        return prefix + "".join(reversed(chars))

    def _parse_cell(s):
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip().upper().replace("$", "")
        m = re.fullmatch(r"([A-Z]{1,3})([1-9][0-9]*)", ss)
        if not m:
            return None
        col_s, row_s = m.group(1), m.group(2)
        col = 0
        for ch in col_s:
            col = col * 26 + (ord(ch) - ord("A") + 1)
        row = int(row_s)
        if not (1 <= col <= 16384 and 1 <= row <= 1048576):
            return None
        return (row, col, f"{col_s}{row}")

    def _log_op(wb_id, ws_id, status, result_payload=None, error_message=None, started_at=None, start=None, end=None):
        ops = _load("range_operations.json")
        ts = _now()
        op_id = _new_id("exop_")
        row = {
            "id": op_id,
            "workbook_id": wb_id or "",
            "worksheet_id": ws_id,
            "tool_name": "merge_cells",
            "operation_scope": "range",
            "start_cell": start,
            "end_cell": end,
            "source_range": None,
            "destination_start_cell": None,
            "shift_direction": None,
            "formula": None,
            "format_spec": None,
            "write_payload": None,
            "read_preview_only": None,
            "request_params": {"workbook_id": workbook_id, "worksheet_id": worksheet_id, "start_cell": start_cell, "end_cell": end_cell},
            "result_payload": result_payload,
            "error_message": error_message,
            "status": status,
            "started_at": started_at or ts,
            "completed_at": ts if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": ts,
            "updated_at": ts,
        }
        ops.append(row); _save("range_operations.json", ops)
        return row

    started = _now()

    if not isinstance(workbook_id, str) or not _ULID_WB.match(workbook_id):
        op = _log_op("", worksheet_id if isinstance(worksheet_id, str) else None, "failed", error_message="workbook_id is malformed.", started_at=started)
        return _err("VALIDATION_ERROR", "workbook_id is malformed.", operation_id=op["id"], workbook_id=workbook_id)
    if not isinstance(worksheet_id, str) or not _ULID_WS.match(worksheet_id):
        op = _log_op(workbook_id, None, "failed", error_message="worksheet_id is malformed.", started_at=started)
        return _err("VALIDATION_ERROR", "worksheet_id is malformed.", operation_id=op["id"], workbook_id=workbook_id, worksheet_id=worksheet_id)

    sc = _parse_cell(start_cell)
    ec = _parse_cell(end_cell)
    if not sc or not ec:
        op = _log_op(workbook_id, worksheet_id, "failed", error_message="start_cell/end_cell must be valid A1 addresses.", started_at=started, start=start_cell, end=end_cell)
        return _err("VALIDATION_ERROR", "start_cell/end_cell must be valid A1 addresses.", operation_id=op["id"], start_cell=start_cell, end_cell=end_cell)
    r1, c1, sc_norm = sc
    r2, c2, ec_norm = ec
    if r2 < r1 or c2 < c1 or (r1 == r2 and c1 == c2):
        op = _log_op(workbook_id, worksheet_id, "failed", error_message="Range must be a non-empty rectangular range (at least 2 cells).", started_at=started, start=sc_norm, end=ec_norm)
        return _err("VALIDATION_ERROR", "Range must be a non-empty rectangular range (at least 2 cells).", operation_id=op["id"], start_cell=sc_norm, end_cell=ec_norm)

    wbs = _load("workbooks.json")
    wbs_rows = wbs["rows"] if isinstance(wbs, dict) and isinstance(wbs.get("rows"), list) else (wbs if isinstance(wbs, list) else [])
    wb = next((w for w in wbs_rows if isinstance(w, dict) and w.get("id") == workbook_id and w.get("status") != "deleted"), None)
    if not wb:
        op = _log_op(workbook_id, worksheet_id, "failed", error_message="Workbook not found (non-deleted).", started_at=started, start=sc_norm, end=ec_norm)
        return _err("NOT_FOUND", "Workbook not found (non-deleted).", operation_id=op["id"], workbook_id=workbook_id)

    wss = _load("worksheets.json")
    wss_rows = wss["rows"] if isinstance(wss, dict) and isinstance(wss.get("rows"), list) else (wss if isinstance(wss, list) else [])
    ws = next((x for x in wss_rows if isinstance(x, dict) and x.get("id") == worksheet_id and x.get("workbook_id") == workbook_id), None)
    if not ws:
        op = _log_op(workbook_id, worksheet_id, "failed", error_message="Worksheet not found in workbook.", started_at=started, start=sc_norm, end=ec_norm)
        return _err("NOT_FOUND", "Worksheet not found in workbook.", operation_id=op["id"], workbook_id=workbook_id, worksheet_id=worksheet_id)
    if ws.get("status") != "active":
        op = _log_op(workbook_id, worksheet_id, "failed", error_message="Worksheet is deleted; merge operation rejected.", started_at=started, start=sc_norm, end=ec_norm)
        return _err("CONFLICT", "Worksheet is deleted; merge operation rejected.", operation_id=op["id"], worksheet_id=worksheet_id)

    # Deterministic merge conflict detection via prior merge_cells ops on same worksheet
    ops = _load("range_operations.json")
    ops_rows = ops["rows"] if isinstance(ops, dict) and isinstance(ops.get("rows"), list) else (ops if isinstance(ops, list) else [])

    def _rect_overlap(a, b):
        # a,b: (r1,c1,r2,c2)
        return not (a[2] < b[0] or b[2] < a[0] or a[3] < b[1] or b[3] < a[1])

    target = (r1, c1, r2, c2)
    existing = []
    for op in ops_rows:
        if not isinstance(op, dict): 
            continue
        if op.get("tool_name") != "merge_cells" or op.get("worksheet_id") != worksheet_id:
            continue
        if op.get("status") != "succeeded":
            continue
        psc = _parse_cell(op.get("start_cell") or "")
        pec = _parse_cell(op.get("end_cell") or "")
        if psc and pec:
            existing.append((psc[0], psc[1], pec[0], pec[1]))

    # Conflict: partial overlap with any existing merge; allow exact same range (idempotent)
    for ex in existing:
        if ex == target:
            result_payload = {"merged_range": f"{sc_norm}:{ec_norm}", "idempotent": True}
            op_row = _log_op(workbook_id, worksheet_id, "succeeded", result_payload=result_payload, started_at=started, start=sc_norm, end=ec_norm)
            return {"operation": op_row, "result": result_payload}
        if _rect_overlap(ex, target):
            # Partial overlap if neither contains the other fully
            contains_target = ex[0] <= target[0] and ex[1] <= target[1] and ex[2] >= target[2] and ex[3] >= target[3]
            contained_by_target = target[0] <= ex[0] and target[1] <= ex[1] and target[2] >= ex[2] and target[3] >= ex[3]
            if not (contains_target or contained_by_target):
                msg = f"Merge conflict: range overlaps existing merged region {op.get('start_cell')}:{op.get('end_cell')}"
                op_row = _log_op(workbook_id, worksheet_id, "failed", error_message=msg, started_at=started, start=sc_norm, end=ec_norm)
                return _err("CONFLICT", msg, operation_id=op_row["id"], workbook_id=workbook_id, worksheet_id=worksheet_id)

    result_payload = {"merged_range": f"{sc_norm}:{ec_norm}"}
    op_row = _log_op(workbook_id, worksheet_id, "succeeded", result_payload=result_payload, started_at=started, start=sc_norm, end=ec_norm)
    return {"operation": op_row, "result": result_payload}

