        col = 0
        for ch in col_s:
            col = col * 26 + (ord(ch) - ord("A") + 1)
        row = int(row_s)
        if not (1 <= col <= 16384 and 1 <= row <= 1048576):
            return None
        return (row, col, f"{col_s}{row}")

    def _parse_range(rng):
        if not isinstance(rng, str) or not rng.strip():
            return None
        s = rng.strip()
        if "!" in s:
            _, s = s.split("!", 1)
            s = s.strip()
        s = s.upper().replace("$", "")
        if ":" in s:
            a, b = [p.strip() for p in s.split(":", 1)]
            p1 = _parse_cell(a)
            p2 = _parse_cell(b)
            if not p1 or not p2:
                return None
            r1, c1, _ = p1
            r2, c2, _ = p2
            if r2 < r1 or c2 < c1:
                return None
            return (r1, c1, r2, c2)
        p = _parse_cell(s)
        if not p:
            return None
        r, c, _ = p
        return (r, c, r, c)

    def _log(status, wb_id, ws_id, error_message=None, result_payload=None, started_at=None):
        ops = _load("range_operations.json")
        ts = _now()
        op_id = _new_id("exop_")
        row = {
            "id": op_id,
            "workbook_id": wb_id or "",
            "worksheet_id": ws_id,
            "tool_name": "copy_range",
            "operation_scope": "range",
            "start_cell": None,
            "end_cell": None,
            "source_range": source_range if isinstance(source_range, str) else None,
            "destination_start_cell": destination_start_cell if isinstance(destination_start_cell, str) else None,
            "shift_direction": None,
            "formula": None,
            "format_spec": None,
            "write_payload": None,
            "read_preview_only": None,
            "request_params": request_params if isinstance(request_params, dict) else ({} if request_params is None else {"raw": request_params}),
            "result_payload": result_payload,
            "error_message": error_message,
            "status": status,
            "started_at": started_at or ts,
            "completed_at": ts if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": ts,
            "updated_at": ts,
        }
        ops.append(row); _save("range_operations.json", ops)
        return row

    started = _now()

    if not isinstance(workbook_id, str) or not _ULID_WB.match(workbook_id):
        op = _log("failed", "", worksheet_id if isinstance(worksheet_id, str) else None, error_message="workbook_id is malformed.", started_at=started)
        return _err("VALIDATION_ERROR", "workbook_id is malformed.", operation_id=op["id"], workbook_id=workbook_id)
    if not isinstance(worksheet_id, str) or not _ULID_WS.match(worksheet_id):
        op = _log("failed", workbook_id, None, error_message="worksheet_id is malformed.", started_at=started)
        return _err("VALIDATION_ERROR", "worksheet_id is malformed.", operation_id=op["id"], workbook_id=workbook_id, worksheet_id=worksheet_id)

    pr = _parse_range(source_range)
    if not pr:
        op = _log("failed", workbook_id, worksheet_id, error_message="source_range must be a valid A1-style range.", started_at=started)
        return _err("VALIDATION_ERROR", "source_range must be a valid A1-style range.", operation_id=op["id"], source_range=source_range)
    dst = _parse_cell(destination_start_cell)
    if not dst:
        op = _log("failed", workbook_id, worksheet_id, error_message="destination_start_cell must be a valid A1 cell address.", started_at=started)
        return _err("VALIDATION_ERROR", "destination_start_cell must be a valid A1 cell address.", operation_id=op["id"], destination_start_cell=destination_start_cell)

    wbs = _load("workbooks.json")
    wbs_rows = wbs["rows"] if isinstance(wbs, dict) and isinstance(wbs.get("rows"), list) else (wbs if isinstance(wbs, list) else [])
    wb = next((w for w in wbs_rows if isinstance(w, dict) and w.get("id") == workbook_id and w.get("status") != "deleted"), None)
    if not wb:
        op = _log("failed", workbook_id, worksheet_id, error_message="Workbook not found (non-deleted).", started_at=started)
        return _err("NOT_FOUND", "Workbook not found (non-deleted).", operation_id=op["id"], workbook_id=workbook_id)

    wss = _load("worksheets.json")
    wss_rows = wss["rows"] if isinstance(wss, dict) and isinstance(wss.get("rows"), list) else (wss if isinstance(wss, list) else [])
    ws = next((x for x in wss_rows if isinstance(x, dict) and x.get("id") == worksheet_id and x.get("workbook_id") == workbook_id), None)
    if not ws:
        op = _log("failed", workbook_id, worksheet_id, error_message="Worksheet not found in workbook.", started_at=started)
        return _err("NOT_FOUND", "Worksheet not found in workbook.", operation_id=op["id"], workbook_id=workbook_id, worksheet_id=worksheet_id)
    if ws.get("status") != "active":
        op = _log("failed", workbook_id, worksheet_id, error_message="Worksheet is deleted; copy operation rejected.", started_at=started)
        return _err("CONFLICT", "Worksheet is deleted; copy operation rejected.", operation_id=op["id"], worksheet_id=worksheet_id)

    r1, c1, r2, c2 = pr
    src_rows = r2 - r1 + 1
    src_cols = c2 - c1 + 1
    dr, dc, dst_norm = dst
    dest_end = (dr + src_rows - 1, dc + src_cols - 1)

    result_payload = {
        "source": {"range": source_range, "r1": r1, "c1": c1, "r2": r2, "c2": c2, "rows": src_rows, "cols": src_cols},
        "destination": {"start_cell": dst_norm, "r": dr, "c": dc, "end_r": dest_end[0], "end_c": dest_end[1]},
    }
    op = _log("succeeded", workbook_id, worksheet_id, result_payload=result_payload, started_at=started)
    return {"operation": op, "resolved": result_payload}

def delete_range(workbook_id, worksheet_id, start_cell, end_cell, shift_direction, request_params=None, **_extra):
    import json, os, datetime, time, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0038000" if __import__("os").path.isdir("./environment_mix/0038000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}
    def _now(): return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _ULID_WB = re.compile(r"^exwb_[0-9A-HJKMNP-TV-Z]{26}$")
    _ULID_WS = re.compile(r"^exws_[0-9A-HJKMNP-TV-Z]{26}$")
    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

    def _new_id(prefix):
        ms = int(time.time() * 1000)
        r = random.getrandbits(80)
        v = (ms << 80) | r
        chars = []
        for _ in range(26):
            chars.append(_B32[v & 31]); v >>= 5
        return prefix + "".join(reversed(chars))

    def _parse_cell(s):
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip().upper().replace("$", "")
        m = re.fullmatch(r"([A-Z]{1,3})([1-9][0-9]*)", ss)
        if not m:
            return None
        col_s, row_s = m.group(1), m.group(2)
        col = 0
        for ch in col_s:
            col = col * 26 + (ord(ch) - ord("A") + 1)
        row = int(row_s)
        if not (1 <= col <= 16384 and 1 <= row <= 1048576):
            return None
        return (row, col, f"{col_s}{row}")

    def _log(status, wb_id, ws_id, sc=None, ec=None, error_message=None, result_payload=None, started_at=None):
        ops = _load("range_operations.json")
        ts = _now()
        row = {
            "id": _new_id("exop_"),
            "workbook_id": wb_id or "",
            "worksheet_id": ws_id,
            "tool_name": "delete_range",
            "operation_scope": "range",
            "start_cell": sc,
            "end_cell": ec,
            "source_range": None,
            "destination_start_cell": None,
            "shift_direction": shift_direction if isinstance(shift_direction, str) else None,
            "formula": None,
            "format_spec": None,
            "write_payload": None,
            "read_preview_only": None,
            "request_params": request_params if isinstance(request_params, dict) else ({} if request_params is None else {"raw": request_params}),
            "result_payload": result_payload,
            "error_message": error_message,
            "status": status,
            "started_at": started_at or ts,
            "completed_at": ts if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": ts,
            "updated_at": ts,
        }
        ops.append(row); _save("range_operations.json", ops)
        return row

    started = _now()

    if not isinstance(workbook_id, str) or not _ULID_WB.match(workbook_id):
        op = _log("failed", "", worksheet_id if isinstance(worksheet_id, str) else None, error_message="workbook_id is malformed.", started_at=started)
        return _err("VALIDATION_ERROR", "workbook_id is malformed.", operation_id=op["id"], workbook_id=workbook_id)
    if not isinstance(worksheet_id, str) or not _ULID_WS.match(worksheet_id):
        op = _log("failed", workbook_id, None, error_message="worksheet_id is malformed.", started_at=started)
        return _err("VALIDATION_ERROR", "worksheet_id is malformed.", operation_id=op["id"], workbook_id=workbook_id, worksheet_id=worksheet_id)
    if shift_direction not in ("up", "left", "none"):
        op = _log("failed", workbook_id, worksheet_id, error_message="shift_direction must be one of: up, left, none.", started_at=started)
        return _err("VALIDATION_ERROR", "shift_direction must be one of: up, left, none.", operation_id=op["id"], shift_direction=shift_direction)

    sc = _parse_cell(start_cell)
    ec = _parse_cell(end_cell)
    if not sc or not ec:
        op = _log("failed", workbook_id, worksheet_id, sc=start_cell, ec=end_cell, error_message="start_cell/end_cell must be valid A1 addresses.", started_at=started)
        return _err("VALIDATION_ERROR", "start_cell/end_cell must be valid A1 addresses.", operation_id=op["id"], start_cell=start_cell, end_cell=end_cell)
    r1, c1, sc_norm = sc
    r2, c2, ec_norm = ec
    if r2 < r1 or c2 < c1:
        op = _log("failed", workbook_id, worksheet_id, sc=sc_norm, ec=ec_norm, error_message="Invalid range: end_cell must be bottom-right of start_cell.", started_at=started)
        return _err("VALIDATION_ERROR", "Invalid range: end_cell must be bottom-right of start_cell.", operation_id=op["id"], start_cell=sc_norm, end_cell=ec_norm)

    wbs = _load("workbooks.json")
    wbs_rows = wbs["rows"] if isinstance(wbs, dict) and isinstance(wbs.get("rows"), list) else (wbs if isinstance(wbs, list) else [])
    wb = next((w for w in wbs_rows if isinstance(w, dict) and w.get("id") == workbook_id and w.get("status") != "deleted"), None)
    if not wb:
        op = _log("failed", workbook_id, worksheet_id, sc=sc_norm, ec=ec_norm, error_message="Workbook not found (non-deleted).", started_at=started)
        return _err("NOT_FOUND", "Workbook not found (non-deleted).", operation_id=op["id"], workbook_id=workbook_id)

    wss = _load("worksheets.json")
    wss_rows = wss["rows"] if isinstance(wss, dict) and isinstance(wss.get("rows"), list) else (wss if isinstance(wss, list) else [])
    ws = next((x for x in wss_rows if isinstance(x, dict) and x.get("id") == worksheet_id and x.get("workbook_id") == workbook_id), None)
    if not ws:
        op = _log("failed", workbook_id, worksheet_id, sc=sc_norm, ec=ec_norm, error_message="Worksheet not found in workbook.", started_at=started)
        return _err("NOT_FOUND", "Worksheet not found in workbook.", operation_id=op["id"], workbook_id=workbook_id, worksheet_id=worksheet_id)
    if ws.get("status") != "active":
        op = _log("failed", workbook_id, worksheet_id, sc=sc_norm, ec=ec_norm, error_message="Worksheet is deleted; delete operation rejected.", started_at=started)
        return _err("CONFLICT", "Worksheet is deleted; delete operation rejected.", operation_id=op["id"], worksheet_id=worksheet_id)

    result_payload = {"deleted_range": f"{sc_norm}:{ec_norm}", "shift_direction": shift_direction}
    op = _log("succeeded", workbook_id, worksheet_id, sc=sc_norm, ec=ec_norm, result_payload=result_payload, started_at=started)
    return {"operation": op, "result": result_payload}

def validate_excel_range(workbook_id, worksheet_id, source_range, request_params=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0038000" if __import__("os").path.isdir("./environment_mix/0038000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now(): return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _ULID_WB = re.compile(r"^exwb_[0-9A-HJKMNP-TV-Z]{26}$")
    _ULID_WS = re.compile(r"^exws_[0-9A-HJKMNP-TV-Z]{26}$")
    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

    def _new_id(prefix):
        ms = int(time.time() * 1000)
        r = random.getrandbits(80)
        v = (ms << 80) | r
        chars = []
        for _ in range(26):
            chars.append(_B32[v & 31]); v >>= 5
        return prefix + "".join(reversed(chars))

    def _col_to_int(col_letters):
        col = 0
        for ch in col_letters:
            col = col * 26 + (ord(ch) - 64)
        return col

    def _parse_a1_cell(s):
        if not isinstance(s, str) or not s.strip():
            return None
        s = s.strip().upper().replace("$", "")
        m = re.fullmatch(r"([A-Z]{1,3})([1-9][0-9]{0,6})", s)
        if not m:
            return None
        c = _col_to_int(m.group(1))
        r = int(m.group(2))
        if not (1 <= c <= 16384 and 1 <= r <= 1048576):
            return None
        return (r, c)

    def _log(status, error_message=None, result_payload=None, start_cell=None, end_cell=None, src_range=None):
        ops = _load("range_operations.json")
        ts = _now()
        row = {
            "id": _new_id("exop_"),
            "workbook_id": workbook_id if isinstance(workbook_id, str) else "",
            "worksheet_id": worksheet_id if isinstance(worksheet_id, str) else None,
            "tool_name": "validate_excel_range",
            "operation_scope": "range",
            "start_cell": start_cell,
            "end_cell": end_cell,
            "source_range": src_range,
            "destination_start_cell": None,
            "shift_direction": None,
            "formula": None,
            "format_spec": None,
            "write_payload": None,
            "read_preview_only": None,
            "request_params": request_params if isinstance(request_params, dict) else ({} if request_params is None else {"raw": request_params}),
            "result_payload": result_payload,
            "error_message": error_message,
            "status": status,
            "started_at": ts,
            "completed_at": ts,
            "created_at": ts,
            "updated_at": ts,
        }
        ops.append(row); _save("range_operations.json", ops)
        return row

    # Validate IDs
    if not isinstance(workbook_id, str) or not _ULID_WB.match(workbook_id):
        op = _log("failed", error_message="workbook_id is malformed.", src_range=source_range)
        return _err("VALIDATION_ERROR", "workbook_id is malformed.", operation_id=op["id"], workbook_id=workbook_id)
    if not isinstance(worksheet_id, str) or not _ULID_WS.match(worksheet_id):
        op = _log("failed", error_message="worksheet_id is malformed.", src_range=source_range)
        return _err("VALIDATION_ERROR", "worksheet_id is malformed.", operation_id=op["id"], worksheet_id=worksheet_id)

    if not isinstance(source_range, str) or source_range.strip() == "":
        op = _log("failed", error_message="source_range must be a non-empty string.", src_range=source_range)
        return _err("VALIDATION_ERROR", "source_range must be a non-empty string.", operation_id=op["id"])

    # Resolve workbook and worksheet
    wbs = _load("workbooks.json")
    wbs_rows = wbs["rows"] if isinstance(wbs, dict) and isinstance(wbs.get("rows"), list) else (wbs if isinstance(wbs, list) else [])
    wb = next((w for w in wbs_rows if isinstance(w, dict) and w.get("id") == workbook_id and w.get("status") != "deleted"), None)
    if not wb:
        op = _log("failed", error_message="Workbook not found (non-deleted).", src_range=source_range)
        return _err("NOT_FOUND", "Workbook not found (non-deleted).", operation_id=op["id"], workbook_id=workbook_id)

    wss = _load("worksheets.json")
    wss_rows = wss["rows"] if isinstance(wss, dict) and isinstance(wss.get("rows"), list) else (wss if isinstance(wss, list) else [])
    ws = next((x for x in wss_rows if isinstance(x, dict) and x.get("id") == worksheet_id and x.get("workbook_id") == workbook_id), None)
    if not ws:
        op = _log("failed", error_message="Worksheet not found in workbook.", src_range=source_range)
        return _err("NOT_FOUND", "Worksheet not found in workbook.", operation_id=op["id"], workbook_id=workbook_id, worksheet_id=worksheet_id)
    if ws.get("status") != "active":
        op = _log("failed", error_message="Worksheet is deleted; validation rejected.", src_range=source_range)
        return _err("CONFLICT", "Worksheet is deleted; validation rejected.", operation_id=op["id"], worksheet_id=worksheet_id)

    # Parse range forms: A1:C10 or single cell. (Do not accept full column/row refs here; tool description example includes A:A,
    # but business rules require non-empty rectangular range; treat A:A as VALIDATION_ERROR syntactically invalid for this server.)
    s = source_range.strip()
    if "!" in s:
        _, s = s.split("!", 1)
        s = s.strip()
    s = s.upper().replace("$", "")

    start = end = None
    if ":" in s:
        a, b = [p.strip() for p in s.split(":", 1)]
        p1 = _parse_a1_cell(a)
        p2 = _parse_a1_cell(b)
        if not p1 or not p2:
            op = _log("failed", error_message="source_range must be a valid A1 rectangular range like A1:C10.", src_range=source_range)
            return _err("VALIDATION_ERROR", "source_range must be a valid A1 rectangular range like A1:C10.", operation_id=op["id"], source_range=source_range)
        start, end = p1, p2
    else:
        p = _parse_a1_cell(s)
        if not p:
            op = _log("failed", error_message="source_range must be a valid A1 address or rectangular range.", src_range=source_range)
            return _err("VALIDATION_ERROR", "source_range must be a valid A1 address or rectangular range.", operation_id=op["id"], source_range=source_range)
        start, end = p, p

    r1, c1 = start
    r2, c2 = end
    if r2 < r1 or c2 < c1:
        op = _log("failed", error_message="Invalid range: end must be bottom-right of start (non-empty rectangular ranges only).", start_cell=None, end_cell=None, src_range=source_range)
        return _err("VALIDATION_ERROR", "Invalid range: end must be bottom-right of start (non-empty rectangular ranges only).", operation_id=op["id"], source_range=source_range)

    # Must be non-empty rectangular; single cell allowed (non-empty rectangle).
    # Validate against worksheet dimensions if dimension_ref available.
    dim = ws.get("dimension_ref")
    max_r = max_c = None
    if isinstance(dim, str) and ":" in dim:
        d1, d2 = [x.strip().upper().replace("$", "") for x in dim.split(":", 1)]
        dp1 = _parse_a1_cell(d1)
        dp2 = _parse_a1_cell(d2)
        if dp1 and dp2:
            max_r = max(dp1[0], dp2[0])
            max_c = max(dp1[1], dp2[1])

    ok = True
    reason = None
    if max_r is not None and max_c is not None:
        if r2 > max_r or c2 > max_c:
            ok = False
            reason = f"Range exceeds known worksheet dimensions ({dim})."

    status = "succeeded" if ok else "failed"
    result_payload = {"is_valid": ok, "reason": reason, "resolved": {"r1": r1, "c1": c1, "r2": r2, "c2": c2}, "worksheet_dimension_ref": dim}
    op = _log(status, error_message=reason if not ok else None, result_payload=result_payload, start_cell=f"{s.split(':',1)[0]}" if isinstance(s, str) else None, end_cell=f"{s.split(':',1)[1]}" if ":" in s else (s if isinstance(s, str) else None), src_range=source_range)

    if ok:
        return {"operation": op, "validation": result_payload}
    return _err("CONFLICT", reason or "Range is not valid for worksheet dimensions.", operation_id=op["id"], workbook_id=workbook_id, worksheet_id=worksheet_id, source_range=source_range)

def list_workbooks(status=None, filepath_contains=None, storage_uri_contains=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0038000" if __import__("os").path.isdir("./environment_mix/0038000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_cursor(c):
        if c is None:
            return 0
        if not isinstance(c, str):
            return None
        try:
            pad = "=" * (-len(c) % 4)
            raw = base64.urlsafe_b64decode((c + pad).encode("utf-8")).decode("utf-8")
            if not raw.startswith("offset:"):
                return None
            off = int(raw.split(":", 1)[1])
            return off if off >= 0 else None
        except Exception:
            return None

    def _make_cursor(off):
        raw = f"offset:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Validation
    allowed_status = {"creating", "active", "archived", "deleted", "error"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        return _err("VALIDATION_ERROR", "Invalid status filter.", allowed=sorted(list(allowed_status)))
    if filepath_contains is not None and not isinstance(filepath_contains, str):
        return _err("VALIDATION_ERROR", "filepath_contains must be a string.")
    if storage_uri_contains is not None and not isinstance(storage_uri_contains, str):
        return _err("VALIDATION_ERROR", "storage_uri_contains must be a string.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    off = _parse_cursor(cursor)
    if off is None:
        return _err("VALIDATION_ERROR", "Invalid cursor.")

    ops = _load("range_operations.json")

    def _log(status_str, error_message=None, result_payload=None):
        now = _now()
        op = {
            "id": f"op_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(ops)+1}",
            "workbook_id": "unknown",
            "worksheet_id": None,
            "tool_name": "get_workbook_metadata",  # closest existing enum for audit; schema doesn't include list_workbooks
            "operation_scope": "workbook",
            "start_cell": None,
            "end_cell": None,
            "source_range": None,
            "destination_start_cell": None,
            "shift_direction": None,
            "formula": None,
            "format_spec": None,
            "write_payload": None,
            "read_preview_only": None,
            "request_params": {
                "status": status,
                "filepath_contains": filepath_contains,
                "storage_uri_contains": storage_uri_contains,
                "limit": limit,
                "cursor": cursor,
            },
            "result_payload": result_payload,
            "error_message": error_message,
            "status": status_str,
            "started_at": now,
            "completed_at": now,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(op)
        _save("range_operations.json", ops)

    wbs = _load("workbooks.json")

    # Filter
    fpq = filepath_contains.lower() if isinstance(filepath_contains, str) and filepath_contains else None
    suq = storage_uri_contains.lower() if isinstance(storage_uri_contains, str) and storage_uri_contains else None

    rows = []
    for wb in wbs:
        if not isinstance(wb, dict):
            continue
        if status is not None and wb.get("status") != status:
            continue
        if fpq:
            fp = wb.get("filepath")
            if not isinstance(fp, str) or fpq not in fp.lower():
                continue
        if suq:
            su = wb.get("storage_uri")
            if not isinstance(su, str) or suq not in su.lower():
                continue
        rows.append(wb)

    def _key_dt(v):
        if not isinstance(v, str):
            return ""
        return v

    # Order by most recently updated
    rows.sort(key=lambda r: (_key_dt(r.get("updated_at")), _key_dt(r.get("created_at")), str(r.get("id", ""))), reverse=True)

    total = len(rows)
    page = rows[off:off + limit]
    next_off = off + len(page)
    has_more = next_off < total
    next_cursor = _make_cursor(next_off) if has_more else None

    resp = {
        "object": "list",
        "data": page,
        "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor, "limit": limit},
    }
    _log("succeeded", result_payload={"returned": len(page), "total": total, "latency_ms": int((time.time() - _t0) * 1000)})
    return resp

