def update_workbook(id, status=None, filepath=None, storage_uri=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0038000" if __import__("os").path.isdir("./environment_mix/0038000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}
    def _now(): return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _resolve_file_path_from_storage_uri(uri):
        if not isinstance(uri, str) or not uri.strip():
            return None
        if uri.startswith("file://"):
            return uri[len("file://"):]
        if "://" not in uri:
            return uri
        return None

    def _sha256_of_path(p):
        h = hashlib.sha256()
        with open(p, "rb") as f:
            for chunk in iter(lambda: f.read(1024 * 1024), b""):
                h.update(chunk)
        return h.hexdigest()

    def _new_op_id():
        # keep exop_ convention
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        rnd = int.from_bytes(hashlib.sha256(f"{ms}|{time.time_ns()}".encode("utf-8")).digest()[:10], "big")
        v = (ms << 80) | rnd
        chars = []
        for _ in range(26):
            chars.append(alphabet[v & 31]); v >>= 5
        return "exop_" + "".join(reversed(chars))

    def _log(tool_status, wb_id_for_log, error_message=None, result_payload=None, started_at=None):
        ops = _load("range_operations.json")
        ts = _now()
        row = {
            "id": _new_op_id(),
            "workbook_id": wb_id_for_log or "",
            "worksheet_id": None,
            "tool_name": "get_workbook_metadata",  # must be one of enum; closest audit/update action available
            "operation_scope": "workbook",
            "start_cell": None,
            "end_cell": None,
            "source_range": None,
            "destination_start_cell": None,
            "shift_direction": None,
            "formula": None,
            "format_spec": None,
            "write_payload": None,
            "read_preview_only": None,
            "request_params": {"id": id, "status": status, "filepath": filepath, "storage_uri": storage_uri},
            "result_payload": result_payload,
            "error_message": error_message,
            "status": tool_status,
            "started_at": started_at or ts,
            "completed_at": ts,
            "created_at": ts,
            "updated_at": ts,
        }
        ops.append(row); _save("range_operations.json", ops)
        return row

    started = _now()

    if not isinstance(id, str) or not id.strip():
        _log("failed", "", error_message="id must be a non-empty string.", started_at=started)
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", id=id)
    if status is not None:
        if not isinstance(status, str) or status not in {"active", "archived", "deleted"}:
            _log("failed", id, error_message="Invalid status. Allowed: active, archived, deleted.", started_at=started)
            return _err("VALIDATION_ERROR", "Invalid status. Allowed: active, archived, deleted.", status=status)
    if filepath is not None and (not isinstance(filepath, str) or not filepath.strip()):
        _log("failed", id, error_message="filepath must be a non-empty string.", started_at=started)
        return _err("VALIDATION_ERROR", "filepath must be a non-empty string.", filepath=filepath)
    if storage_uri is not None and (not isinstance(storage_uri, str) or not storage_uri.strip()):
        _log("failed", id, error_message="storage_uri must be a non-empty string.", started_at=started)
        return _err("VALIDATION_ERROR", "storage_uri must be a non-empty string.", storage_uri=storage_uri)
    if status is None and filepath is None and storage_uri is None:
        _log("failed", id, error_message="No fields to update.", started_at=started)
        return _err("VALIDATION_ERROR", "No fields to update.")

    workbooks = _load("workbooks.json")
    wb = next((w for w in workbooks if isinstance(w, dict) and w.get("id") == id), None)
    if not wb:
        _log("failed", id, error_message="Workbook not found.", started_at=started)
        return _err("NOT_FOUND", "Workbook not found.", id=id)

    # Apply mutable fields with uniqueness enforcement for filepath among non-deleted
    ts = _now()
    if filepath is not None:
        # unique(filepath) WHERE status != 'deleted'
        for other in workbooks:
            if not isinstance(other, dict):
                continue
            if other.get("id") == id:
                continue
            if other.get("status") != "deleted" and other.get("filepath") == filepath:
                _log("failed", id, error_message="unique(filepath) WHERE status != 'deleted' violated.", started_at=started)
                return _err("CONFLICT", "Another non-deleted workbook already uses this filepath.", filepath=filepath)
        wb["filepath"] = filepath

    if storage_uri is not None:
        wb["storage_uri"] = storage_uri

    # Lifecycle transition handling (workbooks schema transitions)
    if status is not None:
        cur = wb.get("status")
        allowed = {
            "creating": {"active", "error"},
            "active": {"archived", "deleted", "error"},
            "archived": {"active", "deleted"},
            "error": {"active", "deleted"},
            "deleted": set(),
        }
        if cur not in allowed:
            _log("failed", id, error_message=f"Unknown current status '{cur}'.", started_at=started)
            return _err("VALIDATION_ERROR", "Workbook has invalid current status.", current_status=cur)

        if status == cur:
            # idempotent
            wb["updated_at"] = ts
            _save("workbooks.json", workbooks)
            op = _log("succeeded", id, result_payload={"id": id, "status": cur, "idempotent": True}, started_at=started)
            return {"workbook": wb, "operation": op}

        if status not in allowed[cur]:
            _log("failed", id, error_message=f"Illegal status transition {cur} -> {status}.", started_at=started)
            return _err("INVALID_TRANSITION", f"Illegal status transition {cur} -> {status}.", id=id, from_status=cur, to_status=status)

        # Activating requires file exists and hash computed
        if status == "active":
            uri = wb.get("storage_uri")
            path = _resolve_file_path_from_storage_uri(uri)
            if not path:
                _log("failed", id, error_message="Cannot activate: storage_uri missing or unsupported.", started_at=started)
                return _err("CONFLICT", "Cannot activate workbook: storage_uri missing or unsupported.", id=id, storage_uri=uri)
            try:
                st = os.stat(path)
            except FileNotFoundError:
                _log("failed", id, error_message="Cannot activate: file missing at storage_uri.", started_at=started)
                return _err("CONFLICT", "Cannot activate workbook: file missing at storage_uri.", id=id, storage_uri=uri)
            except OSError as e:
                _log("failed", id, error_message=f"Cannot activate: cannot access file ({e}).", started_at=started)
                return _err("CONFLICT", "Cannot activate workbook: cannot access file at storage_uri.", id=id, storage_uri=uri)

            try:
                h = _sha256_of_path(path)
            except FileNotFoundError:
                _log("failed", id, error_message="Cannot activate: file missing at storage_uri.", started_at=started)
                return _err("CONFLICT", "Cannot activate workbook: file missing at storage_uri.", id=id, storage_uri=uri)
            except OSError as e:
                _log("failed", id, error_message=f"Cannot activate: cannot read file ({e}).", started_at=started)
                return _err("CONFLICT", "Cannot activate workbook: cannot read file at storage_uri.", id=id, storage_uri=uri)

            wb["file_hash_sha256"] = h
            wb["file_size_bytes"] = int(st.st_size)
            wb["last_modified_at"] = ts

        wb["status"] = status

    wb["updated_at"] = ts
    _save("workbooks.json", workbooks)

    op = _log("succeeded", id, result_payload={"id": id, "status": wb.get("status"), "filepath": wb.get("filepath"), "storage_uri": wb.get("storage_uri")}, started_at=started)
    return {"workbook": wb, "operation": op}

def list_worksheets(workbook_id=None, filepath=None, status=None, visibility=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0038000" if __import__("os").path.isdir("./environment_mix/0038000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_cursor(c):
        if c is None:
            return 0
        if not isinstance(c, str) or not c.strip():
            return None
        try:
            pad = "=" * (-len(c) % 4)
            raw = base64.urlsafe_b64decode((c + pad).encode("utf-8")).decode("utf-8")
            if not raw.startswith("offset:"):
                return None
            off = int(raw.split(":", 1)[1])
            return off if off >= 0 else None
        except Exception:
            return None

    def _make_cursor(off):
        raw = f"offset:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _resolve_workbook(workbooks, workbook_id, filepath):
        if workbook_id is not None and isinstance(workbook_id, str) and workbook_id.strip():
            wb = next((w for w in workbooks if isinstance(w, dict) and w.get("id") == workbook_id.strip() and w.get("status") != "deleted"), None)
            return wb
        if filepath is not None and isinstance(filepath, str) and filepath.strip():
            fp = filepath.strip()
            cand = [w for w in workbooks if isinstance(w, dict) and w.get("filepath") == fp and w.get("status") != "deleted"]
            if not cand:
                return None
            for st in ("active", "archived", "creating", "error"):
                for w in cand:
                    if w.get("status") == st:
                        return w
            return cand[0]
        return None

    def _log_list_call(status_str, wb_id, params, result_payload=None, error_message=None, started_at=None):
        ops = _load("range_operations.json")
        ts = _now()
        op_id = "exop_" + base64.urlsafe_b64encode(os.urandom(18)).decode("utf-8").rstrip("=")[:26]
        row = {
            "id": op_id,
            "workbook_id": wb_id or "",
            "worksheet_id": None,
            "tool_name": "get_workbook_metadata" if False else "list_worksheets",
            "operation_scope": "workbook",
            "start_cell": None,
            "end_cell": None,
            "source_range": None,
            "destination_start_cell": None,
            "shift_direction": None,
            "formula": None,
            "format_spec": None,
            "write_payload": None,
            "read_preview_only": None,
            "request_params": params if isinstance(params, dict) else {"raw": params},
            "result_payload": result_payload,
            "error_message": error_message,
            "status": status_str,
            "started_at": started_at or ts,
            "completed_at": ts if status_str in ("succeeded", "failed", "cancelled") else None,
            "created_at": ts,
            "updated_at": ts,
        }
        ops.append(row)
        _save("range_operations.json", ops)
        return row

    started = _now()
    # Validation: allow either or both workbook_id and filepath (do not reject); prefer workbook_id if given.
    if workbook_id is not None and (not isinstance(workbook_id, str) or not workbook_id.strip()):
        op = _log_list_call("failed", "", {"workbook_id": workbook_id, "filepath": filepath, "status": status, "visibility": visibility, "limit": limit, "cursor": cursor}, error_message="workbook_id must be a non-empty string when provided", started_at=started)
        return _err("VALIDATION_ERROR", "workbook_id must be a non-empty string when provided", operation=op)
    if filepath is not None and (not isinstance(filepath, str) or not filepath.strip()):
        op = _log_list_call("failed", "", {"workbook_id": workbook_id, "filepath": filepath, "status": status, "visibility": visibility, "limit": limit, "cursor": cursor}, error_message="filepath must be a non-empty string when provided", started_at=started)
        return _err("VALIDATION_ERROR", "filepath must be a non-empty string when provided", operation=op)

    if status is None:
        status = "active"
    if not isinstance(status, str) or status not in {"active", "deleted"}:
        op = _log_list_call("failed", "", {"workbook_id": workbook_id, "filepath": filepath, "status": status, "visibility": visibility, "limit": limit, "cursor": cursor}, error_message="Invalid status filter. Allowed: active, deleted.", started_at=started)
        return _err("VALIDATION_ERROR", "Invalid status filter. Allowed: active, deleted.", operation=op)

    if visibility is not None and (not isinstance(visibility, str) or visibility not in {"visible", "hidden", "very_hidden"}):
        op = _log_list_call("failed", "", {"workbook_id": workbook_id, "filepath": filepath, "status": status, "visibility": visibility, "limit": limit, "cursor": cursor}, error_message="Invalid visibility filter.", started_at=started)
        return _err("VALIDATION_ERROR", "Invalid visibility filter.", operation=op)

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        op = _log_list_call("failed", "", {"workbook_id": workbook_id, "filepath": filepath, "status": status, "visibility": visibility, "limit": limit, "cursor": cursor}, error_message="limit must be an integer between 1 and 200", started_at=started)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", operation=op)

    off = _parse_cursor(cursor)
    if off is None:
        op = _log_list_call("failed", "", {"workbook_id": workbook_id, "filepath": filepath, "status": status, "visibility": visibility, "limit": limit, "cursor": cursor}, error_message="Invalid cursor", started_at=started)
        return _err("VALIDATION_ERROR", "Invalid cursor", operation=op)

    workbooks = _load("workbooks.json")
    wb = _resolve_workbook(workbooks, workbook_id, filepath)
    if not wb:
        op = _log_list_call("failed", (workbook_id.strip() if isinstance(workbook_id, str) else ""), {"workbook_id": workbook_id, "filepath": filepath, "status": status, "visibility": visibility, "limit": limit, "cursor": cursor}, error_message="Workbook not found", started_at=started)
        return _err("NOT_FOUND", "Workbook not found", workbook_id=workbook_id, filepath=filepath, operation=op)

    wb_id = wb.get("id") or ""
    worksheets = _load("worksheets.json")
    rows = [w for w in worksheets if isinstance(w, dict) and w.get("workbook_id") == wb_id and w.get("status") == status]
    if visibility is not None:
        rows = [w for w in rows if w.get("visibility") == visibility]

    # Sort by position_index then name then id
    def _k(w):
        pi = w.get("position_index")
        pi = pi if isinstance(pi, int) else 10**9
        nm = w.get("name") or ""
        return (pi, nm.lower(), w.get("id") or "")
    rows.sort(key=_k)

    total = len(rows)
    page = rows[off : off + limit]
    next_off = off + len(page)
    has_more = next_off < total
    next_cursor = _make_cursor(next_off) if has_more else None

    op = _log_list_call("succeeded", wb_id, {"workbook_id": workbook_id, "filepath": filepath, "status": status, "visibility": visibility, "limit": limit, "cursor": cursor}, result_payload={"count": len(page), "total": total, "next_cursor": next_cursor}, started_at=started)
    return {
        "operation": op,
        "items": page,
        "total": total,
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

def list_range_operations(workbook_id=None, filepath=None, worksheet_id=None, sheet_name=None, status=None, tool_name=None, since_created_at=None, until_created_at=None, limit=None, cursor=None, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0038000" if __import__("os").path.isdir("./environment_mix/0038000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return None

    def _parse_rfc3339(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 timestamp string")
        t = s.strip()
        try:
            if t.endswith("Z"):
                dt = datetime.datetime.fromisoformat(t[:-1] + "+00:00")
            else:
                dt = datetime.datetime.fromisoformat(t)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt, None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 timestamp string")

    def _safe_parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            else:
                dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except ValueError:
            return None

    def _gen_req_id():
        # Deterministic enough for local store
        return "req_" + _now().strftime("%Y%m%d%H%M%S%f")

    def _log(endpoint, status_code, resolved_workbook_id=None, resolved_worksheet_id=None, filters=None, cursor_in=None, returned_count=None, total=None, latency_ms=None, error=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _gen_req_id(),
            "endpoint": endpoint,
            "status": status_code,
            "timestamp": _iso(_now()),
            "latency_ms": latency_ms,
            "workbook_id": resolved_workbook_id,
            "worksheet_id": resolved_worksheet_id,
            "filters": filters or {},
            "cursor": cursor_in,
            "returned_count": returned_count,
            "total": total,
            "error": error,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = _now()

    # ---- Validate inputs ----
    if workbook_id is not None and not isinstance(workbook_id, str):
        _log("list_range_operations", "VALIDATION_ERROR", filters={"workbook_id": workbook_id})
        return _err("VALIDATION_ERROR", "workbook_id must be a string")

    if filepath is not None and not isinstance(filepath, str):
        _log("list_range_operations", "VALIDATION_ERROR", filters={"filepath": filepath})
        return _err("VALIDATION_ERROR", "filepath must be a string")

    if worksheet_id is not None and not isinstance(worksheet_id, str):
        _log("list_range_operations", "VALIDATION_ERROR", filters={"worksheet_id": worksheet_id})
        return _err("VALIDATION_ERROR", "worksheet_id must be a string")

    if sheet_name is not None and not isinstance(sheet_name, str):
        _log("list_range_operations", "VALIDATION_ERROR", filters={"sheet_name": sheet_name})
        return _err("VALIDATION_ERROR", "sheet_name must be a string")

    allowed_status = {"queued", "running", "succeeded", "failed", "cancelled"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log("list_range_operations", "VALIDATION_ERROR", filters={"status": status})
            return _err("VALIDATION_ERROR", "status must be one of queued, running, succeeded, failed, cancelled")

    allowed_tool = {
        "create_workbook",
        "get_workbook_metadata",
        "read_data_from_excel",
        "write_data_to_excel",
        "format_range",
        "merge_cells",
        "unmerge_cells",
        "copy_range",
        "delete_range",
        "validate_excel_range",
        "validate_formula_syntax",
        "apply_formula",
        "create_table",
        "create_chart",
        "create_pivot_table",
        "rename_worksheet",
        "copy_worksheet",
        "delete_worksheet",
        "get_data_validation_info",
    }
    if tool_name is not None:
        if not isinstance(tool_name, str) or tool_name not in allowed_tool:
            _log("list_range_operations", "VALIDATION_ERROR", filters={"tool_name": tool_name})
            return _err("VALIDATION_ERROR", "tool_name is invalid")

    if limit is None:
        limit_n = 50
    else:
        if not isinstance(limit, int):
            _log("list_range_operations", "VALIDATION_ERROR", filters={"limit": limit})
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 200:
            _log("list_range_operations", "VALIDATION_ERROR", filters={"limit": limit})
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
        limit_n = limit

    if cursor is not None and not isinstance(cursor, str):
        _log("list_range_operations", "VALIDATION_ERROR", filters={"cursor": cursor})
        return _err("VALIDATION_ERROR", "cursor must be a string")

    since_dt, e = _parse_rfc3339(since_created_at, "since_created_at")
    if e:
        _log("list_range_operations", "VALIDATION_ERROR", filters={"since_created_at": since_created_at})
        return e
    until_dt, e = _parse_rfc3339(until_created_at, "until_created_at")
    if e:
        _log("list_range_operations", "VALIDATION_ERROR", filters={"until_created_at": until_created_at})
        return e
    if since_dt and until_dt and since_dt > until_dt:
        _log("list_range_operations", "VALIDATION_ERROR", filters={"since_created_at": since_created_at, "until_created_at": until_created_at})
        return _err("VALIDATION_ERROR", "since_created_at must be <= until_created_at")

    # ---- Resolve workbook/worksheet references ----
    workbooks = _load("workbooks.json")
    if not isinstance(workbooks, list):
        workbooks = []
    worksheets = _load("worksheets.json")
    if not isinstance(worksheets, list):
        worksheets = []

    resolved_workbook = None

    if workbook_id and filepath:
        # must refer to same workbook
        by_id = next((w for w in workbooks if w.get("id") == workbook_id and w.get("status") != "deleted"), None)
        if by_id is None:
            latency_ms = int((_now() - t0).total_seconds() * 1000)
            _log("list_range_operations", "NOT_FOUND", resolved_workbook_id=None, filters={"workbook_id": workbook_id, "filepath": filepath}, latency_ms=latency_ms, error={"code": "NOT_FOUND", "message": "Workbook not found"})
            return _err("NOT_FOUND", "Workbook not found")
        by_path = [w for w in workbooks if w.get("filepath") == filepath and w.get("status") != "deleted"]
        if len(by_path) != 1 or by_path[0].get("id") != by_id.get("id"):
            latency_ms = int((_now() - t0).total_seconds() * 1000)
            _log("list_range_operations", "NOT_FOUND", resolved_workbook_id=by_id.get("id"), filters={"workbook_id": workbook_id, "filepath": filepath}, latency_ms=latency_ms, error={"code": "NOT_FOUND", "message": "Workbook not found"})
            return _err("NOT_FOUND", "Workbook not found")
        resolved_workbook = by_id
    elif workbook_id:
        resolved_workbook = next((w for w in workbooks if w.get("id") == workbook_id and w.get("status") != "deleted"), None)
        if resolved_workbook is None:
            latency_ms = int((_now() - t0).total_seconds() * 1000)
            _log("list_range_operations", "NOT_FOUND", filters={"workbook_id": workbook_id}, latency_ms=latency_ms, error={"code": "NOT_FOUND", "message": "Workbook not found"})
            return _err("NOT_FOUND", "Workbook not found")
    elif filepath:
        matches = [w for w in workbooks if w.get("filepath") == filepath and w.get("status") != "deleted"]
        if len(matches) != 1:
            latency_ms = int((_now() - t0).total_seconds() * 1000)
            _log("list_range_operations", "NOT_FOUND", filters={"filepath": filepath}, latency_ms=latency_ms, error={"code": "NOT_FOUND", "message": "Workbook not found"})
            return _err("NOT_FOUND", "Workbook not found")
        resolved_workbook = matches[0]

    resolved_worksheet = None

    if sheet_name is not None and resolved_workbook is None:
        latency_ms = int((_now() - t0).total_seconds() * 1000)
        _log("list_range_operations", "VALIDATION_ERROR", filters={"sheet_name": sheet_name}, latency_ms=latency_ms, error={"code": "VALIDATION_ERROR", "message": "sheet_name requires workbook_id or filepath"})
        return _err("VALIDATION_ERROR", "sheet_name requires workbook_id or filepath")

    if worksheet_id and sheet_name:
        # both must match the same worksheet within resolved workbook if provided
        ws = next((s for s in worksheets if s.get("id") == worksheet_id), None)
        if ws is None:
            latency_ms = int((_now() - t0).total_seconds() * 1000)
            _log("list_range_operations", "NOT_FOUND", resolved_workbook_id=(resolved_workbook or {}).get("id"), filters={"worksheet_id": worksheet_id, "sheet_name": sheet_name}, latency_ms=latency_ms, error={"code": "NOT_FOUND", "message": "Worksheet not found"})
            return _err("NOT_FOUND", "Worksheet not found")
        if resolved_workbook and ws.get("workbook_id") != resolved_workbook.get("id"):
            latency_ms = int((_now() - t0).total_seconds() * 1000)
            _log("list_range_operations", "NOT_FOUND", resolved_workbook_id=resolved_workbook.get("id"), resolved_worksheet_id=worksheet_id, filters={"worksheet_id": worksheet_id, "sheet_name": sheet_name}, latency_ms=latency_ms, error={"code": "NOT_FOUND", "message": "Worksheet not found"})
            return _err("NOT_FOUND", "Worksheet not found")
        if ws.get("name") != sheet_name:
            latency_ms = int((_now() - t0).total_seconds() * 1000)
            _log("list_range_operations", "NOT_FOUND", resolved_workbook_id=(resolved_workbook or {}).get("id"), resolved_worksheet_id=worksheet_id, filters={"worksheet_id": worksheet_id, "sheet_name": sheet_name}, latency_ms=latency_ms, error={"code": "NOT_FOUND", "message": "Worksheet not found"})
            return _err("NOT_FOUND", "Worksheet not found")
        resolved_worksheet = ws
    elif worksheet_id:
        ws = next((s for s in worksheets if s.get("id") == worksheet_id), None)
        if ws is None:
            latency_ms = int((_now() - t0).total_seconds() * 1000)
            _log("list_range_operations", "NOT_FOUND", resolved_workbook_id=(resolved_workbook or {}).get("id"), filters={"worksheet_id": worksheet_id}, latency_ms=latency_ms, error={"code": "NOT_FOUND", "message": "Worksheet not found"})
            return _err("NOT_FOUND", "Worksheet not found")
        if resolved_workbook and ws.get("workbook_id") != resolved_workbook.get("id"):
            latency_ms = int((_now() - t0).total_seconds() * 1000)
            _log("list_range_operations", "NOT_FOUND", resolved_workbook_id=resolved_workbook.get("id"), resolved_worksheet_id=worksheet_id, filters={"worksheet_id": worksheet_id}, latency_ms=latency_ms, error={"code": "NOT_FOUND", "message": "Worksheet not found"})
            return _err("NOT_FOUND", "Worksheet not found")
        resolved_worksheet = ws
    elif sheet_name is not None:
        # resolve within workbook (active or deleted; for audit listing, allow any existing worksheet row)
        wb_id = resolved_workbook.get("id")
        matches = [s for s in worksheets if s.get("workbook_id") == wb_id and s.get("name") == sheet_name]
        if len(matches) != 1:
            latency_ms = int((_now() - t0).total_seconds() * 1000)
            _log("list_range_operations", "NOT_FOUND", resolved_workbook_id=wb_id, filters={"sheet_name": sheet_name}, latency_ms=latency_ms, error={"code": "NOT_FOUND", "message": "Worksheet not found"})
            return _err("NOT_FOUND", "Worksheet not found")
        resolved_worksheet = matches[0]

    # If worksheet is specified but workbook isn't, infer workbook for filtering.
    if resolved_worksheet is not None and resolved_workbook is None:
        wb = next((w for w in workbooks if w.get("id") == resolved_worksheet.get("workbook_id") and w.get("status") != "deleted"), None)
        if wb is None:
            latency_ms = int((_now() - t0).total_seconds() * 1000)
            _log("list_range_operations", "NOT_FOUND", resolved_workbook_id=resolved_worksheet.get("workbook_id"), resolved_worksheet_id=resolved_worksheet.get("id"), filters={"worksheet_id": resolved_worksheet.get("id")}, latency_ms=latency_ms, error={"code": "NOT_FOUND", "message": "Workbook not found"})
            return _err("NOT_FOUND", "Workbook not found")
        resolved_workbook = wb

    # ---- Pagination cursor ----
    # Cursor format: "created_at|id" of the last item returned in previous page
    cursor_created_at = None
    cursor_id = None
    if cursor:
        if "|" not in cursor:
            latency_ms = int((_now() - t0).total_seconds() * 1000)
            _log("list_range_operations", "VALIDATION_ERROR", resolved_workbook_id=(resolved_workbook or {}).get("id"), resolved_worksheet_id=(resolved_worksheet or {}).get("id"), filters={"cursor": cursor}, latency_ms=latency_ms, error={"code": "VALIDATION_ERROR", "message": "Invalid cursor"})
            return _err("VALIDATION_ERROR", "Invalid cursor")
        c_ts, c_id = cursor.split("|", 1)
        dt = _safe_parse_dt(c_ts)
        if dt is None or not c_id:
            latency_ms = int((_now() - t0).total_seconds() * 1000)
            _log("list_range_operations", "VALIDATION_ERROR", resolved_workbook_id=(resolved_workbook or {}).get("id"), resolved_worksheet_id=(resolved_worksheet or {}).get("id"), filters={"cursor": cursor}, latency_ms=latency_ms, error={"code": "VALIDATION_ERROR", "message": "Invalid cursor"})
            return _err("VALIDATION_ERROR", "Invalid cursor")
        cursor_created_at = dt
        cursor_id = c_id

    # ---- Load operations and filter ----
    ops = _load("range_operations.json")
    if not isinstance(ops, list):
        ops = []

    wb_id_filter = resolved_workbook.get("id") if resolved_workbook else None
    ws_id_filter = resolved_worksheet.get("id") if resolved_worksheet else None

    filtered = []
    for op in ops:
        if not isinstance(op, dict):
            continue
        if wb_id_filter and op.get("workbook_id") != wb_id_filter:
            continue
        if ws_id_filter and op.get("worksheet_id") != ws_id_filter:
            continue
        if status and op.get("status") != status:
            continue
        if tool_name and op.get("tool_name") != tool_name:
            continue

        cdt = _safe_parse_dt(op.get("created_at"))
        if since_dt and cdt and cdt < since_dt:
            continue
        if since_dt and cdt is None:
            # can't verify, exclude for safety
            continue
        if until_dt and cdt and cdt > until_dt:
            continue
        if until_dt and cdt is None:
            continue

        # cursor: return items strictly after the cursor in descending order,
        # assuming we sort desc by created_at then id.
        if cursor_created_at is not None:
            if cdt is None:
                continue
            if cdt > cursor_created_at:
                # newer than cursor => would have been in previous page; skip
                continue
            if cdt == cursor_created_at:
                # same timestamp: skip ids >= cursor_id for stability in descending id order
                op_id = op.get("id")
                if isinstance(op_id, str) and isinstance(cursor_id, str):
                    if op_id >= cursor_id:
                        continue
                else:
                    continue

        filtered.append(op)

    def _sort_key(op):
        dt = _safe_parse_dt(op.get("created_at"))
        # None sorts last
        dt_key = dt.timestamp() if dt else float("-inf")
        op_id = op.get("id")
        if not isinstance(op_id, str):
            op_id = ""
        return (dt_key, op_id)

    # Sort descending by created_at then id
    filtered.sort(key=_sort_key, reverse=True)

    total = len(filtered)
    page = filtered[:limit_n]
    has_more = total > len(page)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        last_created_at = _safe_parse_dt(last.get("created_at"))
        last_id = last.get("id")
        if last_created_at and isinstance(last_id, str) and last_id:
            next_cursor = _iso(last_created_at) + "|" + last_id

    latency_ms = int((_now() - t0).total_seconds() * 1000)
    _log(
        "list_range_operations",
        "succeeded",
        resolved_workbook_id=wb_id_filter,
        resolved_worksheet_id=ws_id_filter,
        filters={
            "workbook_id": workbook_id,
            "filepath": filepath,
            "worksheet_id": worksheet_id,
            "sheet_name": sheet_name,
            "status": status,
            "tool_name": tool_name,
            "since_created_at": since_created_at,
            "until_created_at": until_created_at,
            "limit": limit_n,
        },
        cursor_in=cursor,
        returned_count=len(page),
        total=total,
        latency_ms=latency_ms,
    )

    return {
        "object": "list",
        "data": page,
        "meta": {
            "total": total,
            "limit": limit_n,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }
